SELECT MAX(`Free Meal Count (K-12)` / `Enrollment (K-12)`) AS highest_eligible_free_rate FROM frpm WHERE `County Name` = 'Alameda';
SELECT      MIN(`Percent (%) Eligible Free (Ages 5-17)`) AS lowest_rate_1,     MIN(`Percent (%) Eligible Free (Ages 5-17)`) AS lowest_rate_2,     MIN(`Percent (%) Eligible Free (Ages 5-17)`) AS lowest_rate_3 FROM frpm WHERE `School Type` = 'Continuation'   AND `Enrollment (Ages 5-17)` IS NOT NULL   AND `Enrollment (Ages 5-17)` > 0;
SELECT     s.Zip FROM schools AS s JOIN frpm AS f     ON s.CDSCode = f.CDSCode WHERE     f.`Charter School (Y/N)` = 1     AND s.District = 'Fresno County Office of Education';
SELECT     s.MailStreet FROM     frpm f JOIN     schools s     ON f.CDSCode = s.CDSCode ORDER BY     f.`FRPM Count (K-12)` DESC LIMIT 1;
SELECT     s.Phone FROM schools AS s JOIN frpm AS f     ON s.CDSCode = f.CDSCode WHERE     f.`Charter School (Y/N)` = 1     AND f.`Charter Funding Type` = 'Directly funded'     AND s.OpenDate > '2000-01-01';
SELECT COUNT(*) AS school_count FROM satscores WHERE AvgScrMath > 400   AND cds IN (     SELECT CDSCode     FROM schools     WHERE Virtual = 'F'   );
SELECT DISTINCT s.School FROM schools s JOIN satscores st ON s.CDSCode = st.cds WHERE st.NumTstTakr > 500   AND s.Magnet = 1;
SELECT s.Phone FROM schools s JOIN satscores st ON s.CDSCode = st.cds ORDER BY st.NumGE1500 DESC LIMIT 1;
SELECT     s.NumTstTakr FROM satscores AS s JOIN frpm AS f     ON s.cds = f.CDSCode WHERE f.`FRPM Count (K-12)` = (     SELECT MAX(`FRPM Count (K-12)`)     FROM frpm );
SELECT COUNT(*) AS charter_funded_count FROM satscores JOIN frpm ON satscores.cds = frpm.CDSCode WHERE satscores.AvgScrMath > 560   AND frpm.`Charter Funding Type` = 'Directly funded';
SELECT f.`FRPM Count (Ages 5-17)` FROM satscores s JOIN frpm f ON s.cds = f.CDSCode ORDER BY s.AvgScrRead DESC LIMIT 1;
SELECT      CDSCode FROM      frpm WHERE      (`Enrollment (K-12)` + `Enrollment (Ages 5-17)`) > 500;
SELECT MAX(f."Free Meal Count (Ages 5-17)" / f."Enrollment (Ages 5-17)") AS highest_eligible_free_rate FROM satscores s JOIN frpm f ON s.cds = f.CDSCode WHERE s.NumTstTakr > 0   AND (s.NumGE1500 * 1.0 / s.NumTstTakr) > 0.3   AND f."Enrollment (Ages 5-17)" > 0;
SELECT     s.Phone FROM schools s JOIN satscores st ON s.CDSCode = st.cds ORDER BY     CAST(st.NumGE1500 AS REAL) / st.NumTstTakr DESC LIMIT 3;
SELECT     s.NCESSchool FROM frpm AS f JOIN schools AS s     ON f.CDSCode = s.CDSCode ORDER BY     f.`Enrollment (Ages 5-17)` DESC LIMIT 5;
SELECT     s.District FROM     schools s JOIN     satscores sat     ON s.CDSCode = sat.cds WHERE     s.StatusType = 'Active'     AND sat.rtype = 'D' GROUP BY     s.District ORDER BY     AVG(sat.AvgScrRead) DESC LIMIT 1;
SELECT COUNT(*) FROM satscores WHERE dname = 'Alameda Unified'   AND NumTstTakr < 100;
SELECT     s.CDSCode,     s.School,     s.CharterNum,     ss.AvgScrWrite FROM schools s JOIN satscores ss ON s.CDSCode = ss.cds WHERE ss.AvgScrWrite > 499   AND s.CharterNum IS NOT NULL ORDER BY ss.AvgScrWrite DESC;
SELECT COUNT(*) FROM satscores JOIN schools ON satscores.cds = schools.CDSCode WHERE schools.County = 'Fresno'   AND schools.FundingType = 'Directly funded'   AND satscores.NumTstTakr <= 250;
SELECT s.Phone FROM schools s JOIN satscores sat ON s.CDSCode = sat.cds ORDER BY sat.AvgScrMath DESC LIMIT 1;
SELECT COUNT(*) FROM frpm WHERE `County Name` = 'Amador'   AND `Low Grade` = '9'   AND `High Grade` = '12';
SELECT COUNT(*) AS school_count FROM frpm WHERE `County Name` = 'Los Angeles'   AND `Free Meal Count (K-12)` > 500   AND `FRPM Count (K-12)` < 700;
SELECT     s.School FROM schools AS s JOIN satscores AS st ON s.CDSCode = st.cds WHERE s.County = 'Contra Costa' ORDER BY st.NumTstTakr DESC LIMIT 1;
SELECT     s.School AS SchoolName,     s.Street AS StreetAddress FROM frpm f JOIN schools s ON f.CDSCode = s.CDSCode WHERE (f.`Enrollment (K-12)` - f.`Enrollment (Ages 5-17)`) > 30;
SELECT     s.School FROM schools s JOIN frpm f     ON s.CDSCode = f.CDSCode JOIN satscores sat     ON s.CDSCode = sat.cds WHERE     f.`Free Meal Count (K-12)` / f.`Enrollment (K-12)` > 0.1     AND sat.NumGE1500 IS NOT NULL     AND sat.NumGE1500 > 0;
SELECT     s.FundingType FROM schools s JOIN satscores t     ON s.CDSCode = t.cds WHERE     s.County = 'Riverside' GROUP BY     s.FundingType HAVING     SUM(t.AvgScrMath) / COUNT(s.CDSCode) > 400;
SELECT     s.School AS SchoolName,     s.Street AS Street,     s.City AS City,     s.State AS State,     s.Zip AS Zip FROM schools s JOIN frpm f     ON s.CDSCode = f.CDSCode WHERE     f.`School Type` = 'High'     AND s.County = 'Monterey'     AND f.`Free Meal Count (Ages 5-17)` > 800;
SELECT     s.School AS SchoolName,     sats.AvgScrWrite AS AvgScrWrite,     s.Phone AS PhoneNumber FROM schools s JOIN satscores sats     ON s.CDSCode = sats.cds WHERE     (s.OpenDate > '1991-12-31')     OR     (s.ClosedDate < '2000-01-01');
WITH avg_diff AS (     SELECT AVG(`Enrollment (K-12)` - `Enrollment (Ages 5-17)`) AS avg_difference     FROM frpm     WHERE `Charter Funding Type` = 'Locally funded' ), school_diff AS (     SELECT          s.`School` AS school_name,         s.`DOCType` AS doc_type,         (f.`Enrollment (K-12)` - f.`Enrollment (Ages 5-17)`) AS difference     FROM frpm f     JOIN schools s ON f.`CDSCode` = s.`CDSCode`     WHERE f.`Charter Funding Type` = 'Locally funded' ) SELECT      sd.school_name,     sd.doc_type FROM school_diff sd CROSS JOIN avg_diff ad WHERE sd.difference > ad.avg_difference;
SELECT s.OpenDate FROM frpm f JOIN schools s ON f.CDSCode = s.CDSCode WHERE f.`Low Grade` = 'K'   AND f.`High Grade` = '12' ORDER BY f.`Enrollment (K-12)` DESC LIMIT 1;
SELECT     s.City FROM schools s JOIN frpm f     ON s.CDSCode = f.CDSCode ORDER BY     f.`Enrollment (K-12)` ASC LIMIT 5;
SELECT      "Free Meal Count (K-12)" / "Enrollment (K-12)" AS eligible_free_rate FROM frpm ORDER BY "Enrollment (K-12)" DESC LIMIT 2 OFFSET 9;
SELECT      f.`FRPM Count (K-12)` / f.`Enrollment (K-12)` AS eligible_free_or_reduced_price_meal_rate FROM frpm f JOIN schools s ON f.`CDSCode` = s.`CDSCode` WHERE s.`DOC` = '66'   AND f.`Low Grade` = 'K'   AND f.`High Grade` = '12' ORDER BY f.`FRPM Count (K-12)` DESC LIMIT 5;
SELECT     s.Website,     s.School FROM schools AS s JOIN frpm AS f     ON s.CDSCode = f.CDSCode WHERE f.`Free Meal Count (Ages 5-17)` BETWEEN 1900 AND 2000;
SELECT      T1.`Free Meal Count (Ages 5-17)` / T1.`Enrollment (Ages 5-17)` AS free_rate FROM frpm AS T1 INNER JOIN schools AS T2     ON T1.CDSCode = T2.CDSCode WHERE      T2.`AdmFName1` = 'Kacey' AND T2.`AdmLName1` = 'Gibson'     OR T2.`AdmFName2` = 'Kacey' AND T2.`AdmLName2` = 'Gibson'     OR T2.`AdmFName3` = 'Kacey' AND T2.`AdmLName3` = 'Gibson';
SELECT s."AdmEmail1" FROM frpm f JOIN schools s ON f."CDSCode" = s."CDSCode" WHERE f."Charter School (Y/N)" = 1 ORDER BY f."Enrollment (K-12)" ASC LIMIT 1;
SELECT     s.AdmFName1 || ' ' || s.AdmLName1 AS Admin1,     s.AdmFName2 || ' ' || s.AdmLName2 AS Admin2,     s.AdmFName3 || ' ' || s.AdmLName3 AS Admin3 FROM schools s JOIN satscores sat ON s.CDSCode = sat.cds ORDER BY sat.NumGE1500 DESC LIMIT 1;
SELECT     s.Street,     s.City,     s.Zip,     s.State FROM schools s JOIN satscores sat ON s.CDSCode = sat.cds ORDER BY (sat.NumGE1500 * 1.0 / sat.NumTstTakr) ASC LIMIT 1;
SELECT s.Website FROM schools s JOIN satscores ss ON s.CDSCode = ss.cds WHERE s.County = 'Los Angeles'   AND ss.NumTstTakr BETWEEN 2000 AND 3000;
SELECT     AVG(s.NumTstTakr) AS average_test_takers FROM satscores AS s JOIN schools AS sc     ON s.cds = sc.CDSCode WHERE     sc.County = 'Fresno'     AND sc.OpenDate BETWEEN '1980-01-01' AND '1980-12-31';
SELECT s.Phone FROM schools s JOIN satscores ss ON s.CDSCode = ss.cds WHERE ss.dname = 'Fresno Unified' ORDER BY ss.AvgScrRead ASC LIMIT 1;
WITH VirtualSchools AS (     SELECT         s.CDSCode,         s.School,         s.County,         sa.AvgScrRead     FROM schools s     JOIN satscores sa ON s.CDSCode = sa.cds     WHERE s.Virtual = 'F' ), RankedSchools AS (     SELECT         CDSCode,         School,         County,         AvgScrRead,         RANK() OVER (PARTITION BY County ORDER BY AvgScrRead DESC) AS rank_in_county     FROM VirtualSchools ) SELECT     School FROM RankedSchools WHERE rank_in_county <= 5;
SELECT     s.EdOpsName FROM satscores AS sat JOIN schools AS s     ON sat.cds = s.CDSCode ORDER BY     sat.AvgScrMath DESC LIMIT 1;
WITH RankedSchools AS (     SELECT         s.cds,         s.AvgScrMath,         s.AvgScrRead,         s.AvgScrWrite,         (s.AvgScrMath + s.AvgScrRead + s.AvgScrWrite) AS TotalScore,         sch.County     FROM satscores s     JOIN schools sch ON s.cds = sch.CDSCode     WHERE s.AvgScrMath IS NOT NULL       AND s.AvgScrRead IS NOT NULL       AND s.AvgScrWrite IS NOT NULL ), LowestScoreSchool AS (     SELECT         cds,         AvgScrMath,         County     FROM RankedSchools     ORDER BY TotalScore ASC     LIMIT 1 ) SELECT     AvgScrMath AS AverageMathScore,     County FROM LowestScoreSchool;
SELECT      satscores.AvgScrWrite,     schools.City FROM satscores JOIN schools ON satscores.cds = schools.CDSCode WHERE satscores.NumGE1500 = (     SELECT MAX(NumGE1500)     FROM satscores ) ORDER BY satscores.NumGE1500 DESC LIMIT 1;
SELECT     s.School,     AVG(ss.AvgScrWrite) AS AvgWritingScore FROM schools s JOIN satscores ss ON s.CDSCode = ss.cds WHERE     s.AdmFName1 = 'Ricci' AND s.AdmLName1 = 'Ulrich'     OR s.AdmFName2 = 'Ricci' AND s.AdmLName2 = 'Ulrich'     OR s.AdmFName3 = 'Ricci' AND s.AdmLName3 = 'Ulrich' GROUP BY s.School;
SELECT     s.School FROM schools s JOIN frpm f     ON s.CDSCode = f.CDSCode WHERE s.DOC = '31' ORDER BY f.`Enrollment (K-12)` DESC LIMIT 1;
SELECT     COUNT(*) / 12.0 AS monthly_average_schools_opened FROM     schools WHERE     County = 'Alameda'     AND DOC = '52'     AND strftime('%Y', OpenDate) = '1980';
SELECT      CAST(SUM(CASE WHEN s.DOC = '54' THEN 1 ELSE 0 END) AS REAL) * 1.0 /      NULLIF(SUM(CASE WHEN s.DOC = '52' THEN 1 ELSE 0 END), 0) AS ratio FROM schools s WHERE s.County = 'Orange'   AND s.StatusType = 'Merged'   AND s.DOC IN ('52', '54');
SELECT     s.County,     s.School,     s.ClosedDate FROM schools AS s WHERE s.StatusType = 'Closed' ORDER BY     (         SELECT COUNT(*)         FROM schools AS s2         WHERE s2.StatusType = 'Closed'           AND s2.County = s.County     ) DESC,     s.County,     s.School;
SELECT     s.MailStreet,     s.School FROM satscores AS sat JOIN schools AS s     ON sat.cds = s.CDSCode ORDER BY     sat.AvgScrMath DESC LIMIT 1 OFFSET 6;
SELECT     s.MailStreet,     s.School FROM schools s JOIN satscores sat ON s.CDSCode = sat.cds ORDER BY sat.AvgScrRead ASC LIMIT 1;
SELECT COUNT(*) AS total_schools FROM satscores s JOIN schools sc ON s.cds = sc.CDSCode WHERE (s.AvgScrRead + s.AvgScrMath + s.AvgScrWrite) >= 1500   AND sc.MailCity = 'Lakeport';
SELECT     SUM(s.NumTstTakr) FROM satscores AS s JOIN schools AS sc     ON s.cds = sc.CDSCode WHERE sc.MailCity = 'Fresno';
SELECT     s.School,     s.MailZip FROM     schools AS s WHERE     s.AdmFName1 = 'Avetik'     AND s.AdmLName1 = 'Atoian';
SELECT      CAST(SUM(CASE WHEN s.County = 'Colusa' THEN 1 ELSE 0 END) AS REAL) * 1.0 /      SUM(CASE WHEN s.County = 'Humboldt' THEN 1 ELSE 0 END) AS ratio FROM schools s WHERE s.MailState = 'CA';
SELECT COUNT(*) FROM schools WHERE MailState = 'CA'   AND City = 'San Joaquin'   AND StatusType = 'Active';
SELECT     s.Phone,     s.Ext FROM satscores AS sat JOIN schools AS s     ON sat.cds = s.CDSCode ORDER BY     sat.AvgScrWrite DESC LIMIT 1 OFFSET 332;
SELECT      s.Phone,     s.Ext,     s.School FROM schools AS s WHERE s.Zip = '95203-3704';
SELECT DISTINCT s.Website FROM schools s WHERE s.AdmFName1 = 'Mike' AND s.AdmLName1 = 'Larson'    OR s.AdmFName2 = 'Mike' AND s.AdmLName2 = 'Larson'    OR s.AdmFName3 = 'Mike' AND s.AdmLName3 = 'Larson'    OR s.AdmFName1 = 'Dante' AND s.AdmLName1 = 'Alvarez'    OR s.AdmFName2 = 'Dante' AND s.AdmLName2 = 'Alvarez'    OR s.AdmFName3 = 'Dante' AND s.AdmLName3 = 'Alvarez';
SELECT      s.Website FROM      schools s WHERE      s.Virtual = 'P'     AND s.Charter = 1     AND s.County = 'San Joaquin';
SELECT COUNT(*) AS chartered_school_count FROM schools WHERE City = 'Hickman'   AND Charter = 1   AND DOC = '52';
SELECT COUNT(*) AS total_non_chartered_schools FROM frpm WHERE `County Name` = 'Los Angeles'   AND `Charter School (Y/N)` = 0   AND (`Free Meal Count (K-12)` * 100.0 / `Enrollment (K-12)`) < 0.18;
SELECT     s.School AS SchoolName,     s.City AS City,     s.AdmFName1 || ' ' || s.AdmLName1 AS Administrator1,     s.AdmFName2 || ' ' || s.AdmLName2 AS Administrator2,     s.AdmFName3 || ' ' || s.AdmLName3 AS Administrator3 FROM schools s WHERE s.Charter = 1   AND s.CharterNum = '00D2';
SELECT COUNT(*) AS total_schools FROM schools WHERE MailCity = 'Hickman'   AND CharterNum = '00D4';
SELECT     (         SUM(CASE WHEN s.FundingType = 'Locally Funded' THEN 1 ELSE 0 END) * 100.0         /         NULLIF(COUNT(*), 0)     ) AS ratio_percentage FROM schools s WHERE s.County = 'Santa Clara';
SELECT COUNT(*) AS directly_funded_schools_count FROM schools WHERE County = 'Stanislaus'   AND FundingType = 'Directly Funded'   AND OpenDate BETWEEN '2000-01-01' AND '2005-12-31';
SELECT COUNT(*) AS total_closure_count FROM schools WHERE DOC = 'Community College District'   AND City = 'San Francisco'   AND strftime('%Y', ClosedDate) = '1989';
SELECT      s.County FROM      schools s WHERE      s.SOC = '11'     AND s.ClosedDate IS NOT NULL     AND s.ClosedDate >= '1980-01-01'     AND s.ClosedDate < '1990-01-01' GROUP BY      s.County ORDER BY      COUNT(*) DESC LIMIT 1;
SELECT     s.NCESDist FROM     schools AS s WHERE     s.SOC = '31';
SELECT COUNT(*) FROM schools WHERE County = 'Alpine'   AND DOC = 'District Community Day School'   AND StatusType IN ('Active', 'Closed');
SELECT      s.District FROM      schools s WHERE      s.City = 'Fresno'     AND s.Magnet = 0;
SELECT     frpm.`Enrollment (Ages 5-17)` FROM frpm JOIN schools     ON frpm.CDSCode = schools.CDSCode WHERE     schools.EdOpsCode = 'SSS'     AND schools.City = 'Fremont'     AND frpm.`Academic Year` = '2014-2015';
SELECT     frpm.`Free Meal Count (Ages 5-17)` FROM frpm JOIN schools     ON frpm.CDSCode = schools.CDSCode WHERE     frpm.`School Name` = 'Youth Authority School'     AND schools.`MailStreet` = 'PO Box 1040';
SELECT     frpm.`Low Grade` FROM     frpm JOIN     schools     ON frpm.`CDSCode` = schools.`CDSCode` WHERE     schools.`EdOpsCode` = 'SPECON'     AND schools.`NCESDist` = '0613360';
SELECT     s.School,     s.EdOpsName FROM schools AS s JOIN frpm AS f     ON s.CDSCode = f.CDSCode WHERE f.`County Code` = '37'   AND f.`NSLP Provision Status` = 'Breakfast Provision 2';
SELECT s.City FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode WHERE s.EILCode = 'HS'   AND f.`NSLP Provision Status` = '2'   AND f.`Low Grade` = '9'   AND f.`High Grade` = '12'   AND f.`County Name` = 'Merced';
SELECT     s.School,     (f.`FRPM Count (Ages 5-17)` / f.`Enrollment (Ages 5-17)` * 100) AS `Percent (%) Eligible FRPM (Ages 5-17)` FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode WHERE s.County = 'Los Angeles'   AND s.GSserved LIKE '%K%'   AND s.GSserved LIKE '%9%'   AND f.`Enrollment (Ages 5-17)` IS NOT NULL   AND f.`Enrollment (Ages 5-17)` <> 0;
SELECT s.GSserved FROM schools s WHERE s.City = 'Adelanto' GROUP BY s.GSserved ORDER BY COUNT(*) DESC LIMIT 1;
SELECT      s.County,     COUNT(*) AS school_count FROM      schools s WHERE      s.County IN ('San Diego', 'Santa Barbara')     AND s.Virtual = 'F' GROUP BY      s.County ORDER BY      school_count DESC LIMIT 1;
SELECT     s.School,     s.Latitude,     f.`School Type` FROM schools AS s JOIN frpm AS f     ON s.CDSCode = f.CDSCode ORDER BY s.Latitude DESC LIMIT 1;
SELECT      s.City,     f.`Low Grade`,     s.School FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode WHERE s.State = 'CA' ORDER BY s.Latitude ASC LIMIT 1;
SELECT     s.GSoffered FROM     schools s ORDER BY     ABS(s.Longitude) DESC LIMIT 1;
SELECT     s.City,     COUNT(*) AS Number_Of_Schools FROM schools s JOIN frpm f     ON s.CDSCode = f.CDSCode WHERE s.Magnet = 1   AND s.GSserved = 'K-8'   AND f.`NSLP Provision Status` = 'Multiple Provision Types' GROUP BY s.City;
WITH admin_names AS (     SELECT         s.District,         s.AdmFName1 AS first_name     FROM schools s     WHERE s.AdmFName1 IS NOT NULL AND s.AdmFName1 <> ''     UNION ALL     SELECT         s.District,         s.AdmFName2 AS first_name     FROM schools s     WHERE s.AdmFName2 IS NOT NULL AND s.AdmFName2 <> ''     UNION ALL     SELECT         s.District,         s.AdmFName3 AS first_name     FROM schools s     WHERE s.AdmFName3 IS NOT NULL AND s.AdmFName3 <> '' ), name_counts AS (     SELECT         first_name,         COUNT(*) AS cnt     FROM admin_names     GROUP BY first_name     ORDER BY cnt DESC, first_name ASC     LIMIT 2 ) SELECT     an.first_name,     an.District FROM admin_names an JOIN name_counts nc   ON an.first_name = nc.first_name ORDER BY nc.cnt DESC, an.first_name ASC, an.District ASC;
SELECT     f.`District Code`,     (f.`Free Meal Count (K-12)` / f.`Enrollment (K-12)`) * 100 AS `Percent (%) Eligible Free (K-12)` FROM frpm AS f JOIN schools AS s   ON f.`CDSCode` = s.`CDSCode` WHERE s.`AdmFName1` = 'Alusine';
SELECT     s.`AdmLName1` AS administrator_last_name,     s.`District` AS district,     s.`County` AS county,     s.`School` AS school_name FROM `schools` AS s WHERE s.`CharterNum` = '40';
SELECT     AdmEmail1 FROM     schools WHERE     County = 'San Bernardino'     AND District = 'San Bernardino City Unified'     AND OpenDate BETWEEN '2009-01-01' AND '2010-12-31'     AND SOC = '62'     AND DOC = '54';
SELECT     s.AdmEmail1,     s.School FROM     satscores AS sat JOIN     schools AS s     ON sat.cds = s.CDSCode ORDER BY     sat.NumGE1500 DESC LIMIT 1;
SELECT COUNT(*) AS account_count FROM account a JOIN district d ON a.district_id = d.district_id WHERE a.frequency = 'POPLATEK PO OBRATU'   AND d.A3 = 'East Bohemia';
SELECT COUNT(*) AS eligible_accounts FROM account a JOIN district d ON a.district_id = d.district_id WHERE d.A3 LIKE '%Prague%';
SELECT      CASE          WHEN AVG(A12) > AVG(A13) THEN '1995'         ELSE '1996'     END AS higher_unemployment_year FROM district;
SELECT COUNT(DISTINCT d.district_id) AS no_of_districts FROM district d JOIN client c ON d.district_id = c.district_id WHERE c.gender = 'F'   AND d.A11 > 6000   AND d.A11 < 10000;
SELECT COUNT(*) AS count FROM client c JOIN district d ON c.district_id = d.district_id WHERE c.gender = 'M'   AND d.A3 = 'North Bohemia'   AND d.A11 > 8000;
WITH client_district AS (     SELECT         c.client_id,         c.gender,         c.birth_date,         d.A11 AS avg_salary     FROM client c     JOIN district d ON c.district_id = d.district_id     WHERE c.gender = 'F' ), ranked AS (     SELECT         cd.*,         ROW_NUMBER() OVER (ORDER BY cd.birth_date ASC, cd.avg_salary ASC) AS rn     FROM client_district cd ), salary_stats AS (     SELECT         MAX(avg_salary) AS max_salary,         MIN(avg_salary) AS min_salary     FROM client_district ) SELECT     a.account_id,     (ss.max_salary - ss.min_salary) AS gap FROM ranked r JOIN disp d ON r.client_id = d.client_id JOIN account a ON d.account_id = a.account_id CROSS JOIN salary_stats ss WHERE r.rn = 1;
SELECT     c.client_id AS account_number FROM     client c JOIN     district d     ON c.district_id = d.district_id ORDER BY     c.birth_date DESC,     d.A11 DESC LIMIT 1;
SELECT COUNT(*) AS owner_count FROM disp d JOIN account a ON d.account_id = a.account_id WHERE a.frequency = 'POPLATEK TYDNE'   AND d.type = 'OWNER';
SELECT DISTINCT c.client_id FROM client c JOIN disp d ON c.client_id = d.client_id JOIN account a ON d.account_id = a.account_id JOIN trans t ON a.account_id = t.account_id WHERE d.type = 'DISPONENT'   AND a.frequency = 'POPLATEK PO OBRATU';
SELECT a.account_id FROM account a JOIN loan l ON a.account_id = l.account_id WHERE l.status = 'A'   AND strftime('%Y', l.date) = '1997'   AND a.frequency = 'POPLATEK TYDNE' ORDER BY l.amount ASC LIMIT 1;
SELECT a.account_id FROM account a JOIN loan l ON a.account_id = l.account_id WHERE l.duration > 12   AND a.date LIKE '1993-%'   AND l.amount = (       SELECT MAX(l2.amount)       FROM loan l2       JOIN account a2 ON l2.account_id = a2.account_id       WHERE l2.duration > 12         AND a2.date LIKE '1993-%'   );
SELECT COUNT(*) AS count FROM client c JOIN district d ON c.district_id = d.district_id JOIN disp disp ON c.client_id = disp.client_id JOIN account a ON disp.account_id = a.account_id WHERE c.gender = 'F'   AND c.birth_date < '1950-01-01'   AND d.A2 = 'Sokolov';
SELECT a.account_id FROM account AS a JOIN trans AS t   ON a.account_id = t.account_id WHERE strftime('%Y', t.date) = '1995'   AND t.date = (       SELECT MIN(t2.date)       FROM trans AS t2       WHERE strftime('%Y', t2.date) = '1995'   );
SELECT DISTINCT a.account_id FROM account a JOIN trans t ON a.account_id = t.account_id WHERE a.date < '1997-01-01'   AND t.amount > 3000;
SELECT c.client_id FROM client c JOIN disp d ON c.client_id = d.client_id JOIN card cd ON d.disp_id = cd.disp_id WHERE cd.issued = '1994-03-03';
SELECT a.date FROM trans t JOIN account a ON t.account_id = a.account_id WHERE t.amount = 840   AND t.date = '1998-10-14';
SELECT a.district_id FROM loan l JOIN account a ON l.account_id = a.account_id WHERE l.date = '1994-08-25';
SELECT MAX(t.amount) AS biggest_amount FROM trans t JOIN disp d ON t.account_id = d.account_id JOIN card c ON d.disp_id = c.disp_id WHERE c.issued = '1996-10-21';
SELECT c.gender FROM client c JOIN district d ON c.district_id = d.district_id WHERE d.A11 = (     SELECT MAX(A11)     FROM district ) ORDER BY c.birth_date ASC LIMIT 1;
WITH client_loans AS (     SELECT          c.client_id,         l.loan_id,         l.amount AS loan_amount,         a.date AS account_open_date     FROM client c     JOIN disp d ON c.client_id = d.client_id     JOIN account a ON d.account_id = a.account_id     JOIN loan l ON a.account_id = l.account_id ), biggest_loan_client AS (     SELECT          client_id,         account_open_date     FROM client_loans     ORDER BY loan_amount DESC     LIMIT 1 ), first_transaction AS (     SELECT          t.amount     FROM trans t     JOIN account a ON t.account_id = a.account_id     JOIN disp d ON a.account_id = d.account_id     JOIN client c ON d.client_id = c.client_id     WHERE c.client_id = (SELECT client_id FROM biggest_loan_client)       AND t.date >= a.date     ORDER BY t.date ASC     LIMIT 1 ) SELECT amount FROM first_transaction;
SELECT COUNT(*) AS female_client_count FROM client c JOIN disp d ON c.client_id = d.client_id JOIN account a ON d.account_id = a.account_id JOIN district dist ON a.district_id = dist.district_id WHERE c.gender = 'F'   AND dist.A2 = 'Jesenik';
SELECT d.disp_id FROM disp AS d JOIN trans AS t ON d.account_id = t.account_id WHERE t.amount = 5100   AND t.date = '1998-09-02';
SELECT COUNT(*) AS account_count FROM account a JOIN district d ON a.district_id = d.district_id WHERE d.A2 = 'Litomerice'   AND strftime('%Y', a.date) = '1996';
SELECT d.A2 FROM client c JOIN disp dp ON c.client_id = dp.client_id JOIN account a ON dp.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE c.gender = 'F'   AND c.birth_date = '1976-01-29';
SELECT c.birth_date FROM loan l JOIN account a ON l.account_id = a.account_id JOIN disp d ON a.account_id = d.account_id JOIN client c ON d.client_id = c.client_id WHERE l.amount = 98832   AND l.date = '1996-01-03';
SELECT a.account_id FROM account a JOIN district d ON a.district_id = d.district_id JOIN disp disp ON a.account_id = disp.account_id JOIN client c ON disp.client_id = c.client_id WHERE d.A3 = 'Prague' ORDER BY a.date ASC LIMIT 1;
WITH south_bohemia_districts AS (     SELECT          d.district_id,         d.A4 AS inhabitants,         c.client_id,         c.gender     FROM district d     JOIN client c ON d.district_id = c.district_id     WHERE d.A3 = 'south Bohemia' ), max_inhabitants AS (     SELECT MAX(inhabitants) AS max_inhabitants     FROM south_bohemia_districts ), target_district AS (     SELECT          s.district_id,         s.client_id,         s.gender     FROM south_bohemia_districts s     JOIN max_inhabitants m ON s.inhabitants = m.max_inhabitants ) SELECT      (CAST(COUNT(CASE WHEN td.gender = 'M' THEN 1 END) AS REAL) * 100.0 / COUNT(td.client_id)) AS percentage_male_clients FROM target_district td;
WITH first_loan AS (     SELECT          l.account_id,         l.date AS loan_date     FROM loan l     WHERE l.status = 'A'     ORDER BY l.date ASC     LIMIT 1 ), client_account AS (     SELECT          d.account_id     FROM disp d     JOIN first_loan fl ON d.account_id = fl.account_id     WHERE d.type = 'OWNER' ), balances AS (     SELECT          t.account_id,         t.date,         t.balance     FROM trans t     JOIN client_account ca ON t.account_id = ca.account_id     WHERE t.date IN ('1993-03-22', '1998-12-27') ) SELECT      ((b2.balance - b1.balance) * 100.0 / b1.balance) AS increase_rate FROM balances b1 JOIN balances b2 ON b1.account_id = b2.account_id WHERE b1.date = '1993-03-22'   AND b2.date = '1998-12-27';
SELECT      (SUM(CASE WHEN status = 'A' THEN amount ELSE 0 END) * 100.0) / SUM(amount) AS percentage FROM loan;
SELECT      CAST(SUM(CASE WHEN l.status = 'C' THEN l.amount ELSE 0 END) AS REAL) * 100 / SUM(l.amount) AS percentage FROM      loan l WHERE      l.amount < 100000;
SELECT     a.account_id,     d.A2 AS district_name,     d.A3 AS district_region FROM account a JOIN district d     ON a.district_id = d.district_id WHERE     a.date = '1993-01-01'       AND a.frequency = 'POPLATEK PO OBRATU';
SELECT     a.account_id,     a.frequency FROM account AS a JOIN district AS d     ON a.district_id = d.district_id JOIN disp AS dp     ON a.account_id = dp.account_id WHERE     d.A3 = 'east Bohemia'     AND a.date >= '1995-01-01'     AND a.date <= '2000-12-31'     AND dp.type = 'OWNER';
SELECT     a.account_id,     a.date FROM account AS a JOIN district AS d     ON a.district_id = d.district_id WHERE d.A2 = 'Prachatice';
SELECT d.A2 AS district, d.A3 AS region FROM loan l JOIN account a ON l.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE l.loan_id = 4990;
SELECT     l.account_id,     d.A2 AS district,     d.A3 AS region FROM loan AS l JOIN account AS a     ON l.account_id = a.account_id JOIN district AS d     ON a.district_id = d.district_id WHERE l.amount > 300000;
SELECT      l.loan_id,     d.A3 AS district,     d.A11 AS average_salary FROM loan l JOIN account a ON l.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE l.duration = 60;
SELECT     d.A2 AS district,     ((d.A13 - d.A12) / d.A12) * 100 AS unemployment_increment_rate FROM loan l JOIN account a ON l.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE l.status = 'D';
SELECT      CAST(SUM(CASE WHEN a.date LIKE '1993-%' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS percentage FROM account a JOIN district d ON a.district_id = d.district_id WHERE d.A2 = 'Decin';
SELECT account_id FROM account WHERE frequency = 'POPLATEK MESICNE';
SELECT      d.A2,     COUNT(c.client_id) AS female_account_holders FROM district d JOIN client c ON d.district_id = c.district_id JOIN disp disp ON c.client_id = disp.client_id JOIN account a ON disp.account_id = a.account_id WHERE c.gender = 'F' GROUP BY d.A2 ORDER BY female_account_holders DESC LIMIT 9;
SELECT     d.A2 AS district_name,     t.amount FROM trans t JOIN account a ON t.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE t.type = 'VYDAJ'   AND t.date LIKE '1996-01%' ORDER BY t.amount DESC LIMIT 10;
SELECT COUNT(*) FROM account a JOIN district d ON a.district_id = d.district_id JOIN disp disp ON a.account_id = disp.account_id JOIN client c ON disp.client_id = c.client_id WHERE d.A3 = 'South Bohemia'   AND disp.type = 'OWNER'   AND NOT EXISTS (       SELECT 1       FROM card card       JOIN disp disp2 ON card.disp_id = disp2.disp_id       WHERE disp2.client_id = c.client_id   );
SELECT d.A3 FROM loan l JOIN account a ON l.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE l.status IN ('C', 'D') ORDER BY l.amount DESC LIMIT 1;
SELECT AVG(l.amount) AS average_loan_amount FROM loan l JOIN account a ON l.account_id = a.account_id JOIN disp d ON a.account_id = d.account_id JOIN client c ON d.client_id = c.client_id WHERE c.gender = 'M';
SELECT      d.A4 AS branch_location,     d.A2 AS district_name FROM      district d WHERE      d.A13 = (         SELECT              MAX(d2.A13)         FROM              district d2     );
SELECT COUNT(a.account_id) AS accounts_opened FROM account a JOIN district d ON a.district_id = d.district_id WHERE d.A16 = (     SELECT MAX(A16)     FROM district );
SELECT COUNT(DISTINCT a.account_id) AS account_count FROM account a JOIN trans t ON a.account_id = t.account_id WHERE a.frequency = 'POPLATEK MESICNE'   AND t.operation = 'VYBER KARTOU'   AND t.balance < 0;
SELECT COUNT(*) AS loan_count FROM loan l JOIN account a ON l.account_id = a.account_id WHERE l.date BETWEEN '1995-01-01' AND '1997-12-31'   AND l.amount >= 250000   AND a.frequency = 'POPLATEK MESICNE';
SELECT COUNT(*) AS account_count FROM loan WHERE status IN ('C', 'D')   AND account_id IN (     SELECT account_id     FROM account     WHERE district_id = 1   );
SELECT COUNT(c.client_id) AS male_client_count FROM client c JOIN district d ON c.district_id = d.district_id WHERE d.district_id = (     SELECT district_id     FROM district     ORDER BY A15 DESC     LIMIT 1 OFFSET 1 );
