SELECT AVG(t.amount) AS average_amount FROM trans t JOIN account a ON t.account_id = a.account_id WHERE t.operation = 'VYBER KARTOU'   AND strftime('%Y', t.date) = '2021'   AND strftime('%m', t.date) = '01';
