SELECT DISTINCT a.account_id FROM account a JOIN district d ON a.district_id = d.district_id JOIN disp dp ON a.account_id = dp.account_id WHERE d.A2 = 'Tabor'   AND dp.type = 'OWNER';
SELECT DISTINCT     d.type AS account_type,     dist.A11 AS average_income FROM disp d JOIN account a   ON d.account_id = a.account_id JOIN district dist   ON a.district_id = dist.district_id WHERE d.type <> 'OWNER'   AND dist.A11 > 8000   AND dist.A11 <= 9000;
SELECT COUNT(DISTINCT t.account_id) AS account_count FROM trans t JOIN account a ON t.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE d.A3 = 'North Bohemia'   AND t.bank = 'AB';
