SELECT      CAST(SUM(CASE WHEN c.gender = 'F' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS percentage FROM client c JOIN disp d ON c.client_id = d.client_id JOIN account a ON d.account_id = a.account_id JOIN district dist ON a.district_id = dist.district_id WHERE dist.A11 > 10000;
WITH male_accounts AS (     SELECT DISTINCT d.account_id     FROM disp d     JOIN client c ON d.client_id = c.client_id     WHERE c.gender = 'M' ), loan_amounts AS (     SELECT          l.account_id,         l.amount,         CASE              WHEN l.date >= '1996-01-01' AND l.date < '1997-01-01' THEN '1996'             WHEN l.date >= '1997-01-01' AND l.date < '1998-01-01' THEN '1997'         END AS year     FROM loan l     JOIN male_accounts ma ON l.account_id = ma.account_id     WHERE (l.date >= '1996-01-01' AND l.date < '1998-01-01') ) SELECT      (SUM(CASE WHEN year = '1997' THEN amount ELSE 0 END) - SUM(CASE WHEN year = '1996' THEN amount ELSE 0 END)) * 100.0 /      NULLIF(SUM(CASE WHEN year = '1996' THEN amount ELSE 0 END), 0) AS growth_rate FROM loan_amounts;
