SELECT COUNT(*) AS count FROM cards c JOIN legalities l ON c.uuid = l.uuid WHERE c.rarity = 'rare'   AND c.types = 'Enchantment'   AND c.name = 'Abundance'   AND l.status = 'Legal';
WITH BannedCounts AS (     SELECT         l.format,         COUNT(*) AS banned_count     FROM legalities l     WHERE l.status = 'Banned'     GROUP BY l.format ), TopFormat AS (     SELECT         format     FROM BannedCounts     ORDER BY banned_count DESC     LIMIT 1 ) SELECT     tf.format,     c.name FROM TopFormat tf JOIN legalities l   ON l.format = tf.format  AND l.status = 'Banned' JOIN cards c   ON c.uuid = l.uuid ORDER BY c.name;
SELECT     st.language FROM sets AS s JOIN set_translations AS st     ON st.setCode = s.code WHERE s.name = 'Battlebond';
SELECT     l.format FROM cards AS c JOIN legalities AS l     ON c.uuid = l.uuid WHERE c.artist = (     SELECT artist     FROM cards     WHERE artist IS NOT NULL     GROUP BY artist     ORDER BY COUNT(*) ASC, artist ASC     LIMIT 1 );
SELECT     l.status FROM cards AS c JOIN legalities AS l     ON c.uuid = l.uuid WHERE     c.frameVersion = '1997'     AND c.artist = 'D. Alexander Gregory'     AND c.hasContentWarning = 1     AND l.format = 'legacy';
SELECT     c.name,     l.format FROM cards AS c JOIN legalities AS l     ON c.uuid = l.uuid WHERE     c.edhrecRank = 1     AND l.status = 'Banned';
WITH filtered_sets AS (     SELECT          s.id,         s.releaseDate     FROM sets s     WHERE s.releaseDate BETWEEN '2012-01-01' AND '2015-12-31' ), language_counts AS (     SELECT          fd.language,         COUNT(fd.language) AS lang_count     FROM foreign_data fd     WHERE fd.language IS NOT NULL     GROUP BY fd.language ), top_language AS (     SELECT          language     FROM language_counts     ORDER BY lang_count DESC     LIMIT 1 ), yearly_counts AS (     SELECT          strftime('%Y', fs.releaseDate) AS release_year,         COUNT(fs.id) AS set_count     FROM filtered_sets fs     GROUP BY strftime('%Y', fs.releaseDate) ) SELECT      AVG(yc.set_count) AS annual_average_sets FROM yearly_counts yc CROSS JOIN top_language tl;
SELECT DISTINCT c.artist FROM cards AS c WHERE c.borderColor = 'black'   AND c.availability = 'arena';
