SELECT s.superhero_name FROM superhero s JOIN colour c ON s.eye_colour_id = c.id WHERE s.height_cm BETWEEN 170 AND 190   AND c.colour = 'No Colour';
SELECT sp.power_name FROM hero_power hp JOIN superpower sp ON hp.power_id = sp.id WHERE hp.hero_id = 56;
SELECT     s.full_name FROM superhero AS s JOIN race AS r     ON s.race_id = r.id WHERE r.race = 'Demi-God' LIMIT 5;
SELECT COUNT(*) AS count FROM superhero s JOIN alignment a ON s.alignment_id = a.id WHERE a.alignment = 'Bad';
SELECT r.race FROM superhero s JOIN race r ON s.race_id = r.id WHERE s.weight_kg = 169;
SELECT c.colour FROM superhero s JOIN colour c ON s.hair_colour_id = c.id JOIN race r ON s.race_id = r.id WHERE s.height_cm = 185   AND r.race = 'Human';
SELECT c.colour FROM superhero s JOIN colour c ON s.eye_colour_id = c.id ORDER BY s.weight_kg DESC LIMIT 1;
SELECT      CAST(SUM(CASE WHEN p.publisher_name = 'Marvel Comics' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(p.id) AS percentage FROM superhero s JOIN publisher p ON s.publisher_id = p.id WHERE s.height_cm BETWEEN 150 AND 180;
SELECT s.superhero_name FROM superhero s JOIN gender g ON s.gender_id = g.id WHERE g.gender = 'Male'   AND s.weight_kg > (SELECT AVG(weight_kg) * 0.79 FROM superhero);
SELECT     sp.power_name FROM     hero_power hp JOIN     superpower sp     ON hp.power_id = sp.id GROUP BY     sp.power_name ORDER BY     COUNT(sp.power_name) DESC LIMIT 1;
SELECT     ha.attribute_value FROM superhero AS s JOIN hero_attribute AS ha     ON s.id = ha.hero_id WHERE     s.superhero_name = 'Abomination';
SELECT sp.power_name FROM hero_power hp JOIN superpower sp ON hp.power_id = sp.id WHERE hp.hero_id = 1;
SELECT COUNT(DISTINCT hp.hero_id) AS hero_count FROM hero_power hp JOIN superpower sp ON hp.power_id = sp.id WHERE sp.power_name = 'Stealth';
SELECT     s.full_name FROM superhero AS s JOIN hero_attribute AS ha     ON s.id = ha.hero_id JOIN attribute AS a     ON ha.attribute_id = a.id WHERE a.attribute_name = 'Strength' ORDER BY ha.attribute_value DESC LIMIT 1;
SELECT     CAST(COUNT(s.id) AS REAL) / SUM(CASE WHEN s.skin_colour_id = 1 THEN 1 ELSE 0 END) AS average FROM superhero AS s;
SELECT COUNT(*) AS count FROM superhero s JOIN publisher p ON s.publisher_id = p.id WHERE p.publisher_name = 'Dark Horse Comics';
SELECT     s.superhero_name FROM superhero AS s JOIN hero_attribute AS ha     ON s.id = ha.hero_id JOIN attribute AS a     ON ha.attribute_id = a.id JOIN publisher AS p     ON s.publisher_id = p.id WHERE     a.attribute_name = 'Durability'     AND p.publisher_name = 'Dark Horse Comics' ORDER BY     ha.attribute_value DESC LIMIT 1;
SELECT c.colour FROM superhero s JOIN colour c ON s.eye_colour_id = c.id WHERE s.full_name = 'Abraham Sapien';
SELECT     s.superhero_name FROM superhero AS s JOIN hero_power AS hp     ON s.id = hp.hero_id JOIN superpower AS sp     ON hp.power_id = sp.id WHERE     sp.power_name = 'Flight';
SELECT     ec.colour AS eyes,     hc.colour AS hair,     sc.colour AS skin_colour FROM superhero s JOIN gender g ON s.gender_id = g.id JOIN publisher p ON s.publisher_id = p.id JOIN colour ec ON s.eye_colour_id = ec.id JOIN colour hc ON s.hair_colour_id = hc.id JOIN colour sc ON s.skin_colour_id = sc.id WHERE g.gender = 'Female'   AND p.publisher_name = 'Dark Horse Comics';
SELECT     s.superhero_name,     p.publisher_name FROM superhero AS s JOIN publisher AS p     ON s.publisher_id = p.id WHERE s.hair_colour_id = s.skin_colour_id   AND s.hair_colour_id = s.eye_colour_id;
SELECT r.race FROM superhero s JOIN race r ON s.race_id = r.id WHERE s.superhero_name = 'A-Bomb';
SELECT      CAST(SUM(CASE WHEN c.colour = 'Blue' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS percentage FROM superhero s JOIN gender g ON s.gender_id = g.id JOIN colour c ON s.skin_colour_id = c.id WHERE g.gender = 'Female';
SELECT     s.superhero_name,     r.race FROM superhero AS s JOIN race AS r     ON s.race_id = r.id WHERE s.full_name = 'Charles Chandler';
SELECT g.gender FROM superhero s JOIN gender g ON s.gender_id = g.id WHERE s.superhero_name = 'Agent 13';
SELECT s.superhero_name FROM superhero AS s JOIN hero_power AS hp ON s.id = hp.hero_id JOIN superpower AS sp ON hp.power_id = sp.id WHERE sp.power_name = 'Adaptation';
SELECT COUNT(*) AS power_count FROM hero_power hp JOIN superhero s ON hp.hero_id = s.id WHERE s.superhero_name = 'Amazo';
SELECT sp.power_name FROM superhero s JOIN hero_power hp ON s.id = hp.hero_id JOIN superpower sp ON hp.power_id = sp.id WHERE s.full_name = 'Hunter Zolomon';
SELECT     s.height_cm FROM superhero AS s JOIN colour AS c     ON s.eye_colour_id = c.id WHERE     c.colour = 'Amber';
