SELECT     s.superhero_name FROM superhero AS s JOIN colour AS c_eyes ON s.eye_colour_id = c_eyes.id JOIN colour AS c_hair ON s.hair_colour_id = c_hair.id WHERE     c_eyes.colour = 'Blue'     AND c_hair.colour = 'Brown';
SELECT p.publisher_name FROM superhero s JOIN publisher p ON s.publisher_id = p.id WHERE s.superhero_name IN ('Hawkman', 'Karate Kid', 'Speedy');
