SELECT     CAST(SUM(CASE WHEN c.colour = 'Blue' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(s.superhero_name) AS percentage FROM superhero s JOIN colour c ON s.eye_colour_id = c.id;
SELECT      CAST(SUM(CASE WHEN g.gender = 'Male' THEN 1 ELSE 0 END) AS REAL) * 1.0 /      NULLIF(SUM(CASE WHEN g.gender = 'Female' THEN 1 ELSE 0 END), 0) AS ratio FROM superhero s JOIN gender g ON s.gender_id = g.id;
SELECT s.superhero_name FROM superhero AS s ORDER BY s.height_cm DESC LIMIT 1;
