SELECT     s.superhero_name FROM superhero AS s JOIN hero_power AS hp     ON s.id = hp.hero_id JOIN superpower AS sp     ON hp.power_id = sp.id WHERE     sp.power_name = 'Wind Control' ORDER BY     s.superhero_name ASC;
SELECT     g.gender FROM superhero AS s JOIN gender AS g     ON s.gender_id = g.id JOIN hero_power AS hp     ON s.id = hp.hero_id JOIN superpower AS sp     ON hp.power_id = sp.id WHERE     sp.power_name = 'Phoenix Force';
SELECT s.superhero_name FROM superhero s JOIN publisher p ON s.publisher_id = p.id WHERE p.publisher_name = 'DC Comics' ORDER BY s.weight_kg DESC LIMIT 1;
SELECT AVG(s.height_cm) AS average_height FROM superhero s JOIN race r ON s.race_id = r.id JOIN publisher p ON s.publisher_id = p.id WHERE r.race <> 'Human'   AND p.publisher_name = 'Dark Horse Comics';
