SELECT      CAST(SUM(CASE WHEN a.alignment = 'Good' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) AS percentage FROM superhero s JOIN publisher p ON s.publisher_id = p.id JOIN alignment a ON s.alignment_id = a.id WHERE p.publisher_name = 'Marvel Comics';
SELECT COUNT(*) AS total_superheroes FROM superhero WHERE full_name LIKE 'John%';
SELECT     hero_id FROM     hero_attribute ORDER BY     attribute_value ASC LIMIT 1;
SELECT s.full_name FROM superhero s JOIN race r ON s.race_id = r.id WHERE s.superhero_name = 'Alien';
SELECT     s.full_name FROM superhero AS s JOIN colour AS c     ON s.eye_colour_id = c.id WHERE     s.weight_kg < 100     AND c.colour = 'Brown';
SELECT     ha.attribute_value FROM superhero AS s JOIN hero_attribute AS ha     ON s.id = ha.hero_id WHERE     s.superhero_name = 'Aquababy';
SELECT     s.weight_kg,     r.race FROM superhero AS s LEFT JOIN race AS r     ON s.race_id = r.id WHERE s.id = 40;
SELECT AVG(s.height_cm) AS average_height FROM superhero s JOIN alignment a ON s.alignment_id = a.id WHERE a.alignment = 'Neutral';
SELECT     sp.hero_id FROM hero_power AS sp JOIN superpower AS s     ON sp.power_id = s.id WHERE s.power_name = 'Intelligence';
SELECT c.colour FROM superhero s JOIN colour c ON s.eye_colour_id = c.id WHERE s.superhero_name = 'Blackwulf';
SELECT     sp.power_name FROM superhero AS s JOIN hero_power AS hp     ON s.id = hp.hero_id JOIN superpower AS sp     ON hp.power_id = sp.id WHERE s.height_cm > (     SELECT AVG(height_cm) * 0.8     FROM superhero );
SELECT d.driverRef FROM qualifying q JOIN drivers d ON q.driverId = d.driverId WHERE q.raceId = 20   AND q.q1 IN (       SELECT q1       FROM qualifying       WHERE raceId = 20       ORDER BY q1 DESC       LIMIT 5   );
SELECT d.surname FROM qualifying q JOIN drivers d ON q.driverId = d.driverId WHERE q.raceId = 19   AND q.q2 IS NOT NULL ORDER BY q.q2 ASC LIMIT 1;
SELECT DISTINCT r.year FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE c.location = 'Shanghai';
SELECT     r.url FROM races AS r JOIN circuits AS c     ON r.circuitId = c.circuitId WHERE c.name = 'Circuit de Barcelona-Catalunya';
SELECT     r.name FROM races AS r JOIN circuits AS c     ON r.circuitId = c.circuitId WHERE c.country = 'Germany';
SELECT     c.circuitId,     c.name,     c.location,     c.country FROM circuits AS c JOIN races AS r     ON c.circuitId = r.circuitId JOIN constructorResults AS cr     ON r.raceId = cr.raceId JOIN constructors AS cons     ON cr.constructorId = cons.constructorId WHERE cons.name = 'Renault';
SELECT COUNT(*) FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE r.year = 2010   AND c.country NOT IN ('Asia', 'Europe');
SELECT     r.name FROM races AS r JOIN circuits AS c     ON r.circuitId = c.circuitId WHERE c.country = 'Spain';
SELECT     c.lat,     c.lng FROM circuits AS c JOIN races AS r     ON c.circuitId = r.circuitId WHERE r.name = 'Australian Grand Prix';
SELECT r.url FROM races AS r JOIN circuits AS c ON r.circuitId = c.circuitId WHERE c.name = 'Sepang International Circuit';
SELECT     r.time FROM races AS r JOIN circuits AS c     ON r.circuitId = c.circuitId WHERE c.name = 'Sepang International Circuit';
SELECT     c.lat,     c.lng FROM races AS r JOIN circuits AS c     ON r.circuitId = c.circuitId WHERE r.name = 'Abu Dhabi Grand Prix';
SELECT c.nationality FROM constructorResults cr JOIN constructors c ON cr.constructorId = c.constructorId WHERE cr.raceId = 24   AND cr.points = 1;
SELECT     q.q1 FROM qualifying AS q JOIN drivers AS d     ON q.driverId = d.driverId JOIN races AS r     ON q.raceId = r.raceId WHERE     d.forename = 'Bruno'     AND d.surname = 'Senna'     AND r.raceId = 354;
SELECT d.nationality FROM qualifying q JOIN drivers d ON q.driverId = d.driverId WHERE q.raceId = 355   AND q.q2 = '0:01:40';
SELECT     d.number FROM qualifying q JOIN drivers d     ON q.driverId = d.driverId WHERE     q.raceId = 903     AND q.q3 LIKE '1:54%';
SELECT COUNT(DISTINCT r.driverId) AS drivers_not_finished FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.name = 'Bahrain Grand Prix'   AND ra.year = 2007   AND r.time IS NULL;
SELECT s.url FROM races r JOIN seasons s ON r.year = s.year WHERE r.raceId = 901;
SELECT COUNT(DISTINCT r.driverId) AS finished_drivers FROM results r JOIN races ra ON r.raceId = ra.raceId JOIN status s ON r.statusId = s.statusId WHERE ra.date = '2015-11-29'   AND s.status = 'Finished'   AND r.time IS NOT NULL;
SELECT d.* FROM drivers d JOIN results r ON d.driverId = r.driverId WHERE r.raceId = 592   AND r.time IS NOT NULL ORDER BY d.dob ASC LIMIT 1;
SELECT d.url FROM lapTimes lt JOIN drivers d ON lt.driverId = d.driverId WHERE lt.raceId = 161   AND lt.time LIKE '1:27%';
SELECT d.nationality FROM results r JOIN drivers d ON r.driverId = d.driverId WHERE r.raceId = 933   AND r.fastestLapSpeed = (       SELECT MAX(fastestLapSpeed)       FROM results       WHERE raceId = 933   );
SELECT     c.lat,     c.lng FROM races AS r JOIN circuits AS c     ON r.circuitId = c.circuitId WHERE r.name = 'Malaysian Grand Prix';
SELECT c.url FROM constructorResults cr JOIN constructors c ON cr.constructorId = c.constructorId WHERE cr.raceId = 9 ORDER BY cr.points DESC LIMIT 1;
SELECT     q.q1 FROM qualifying AS q JOIN drivers AS d     ON q.driverId = d.driverId WHERE     d.forename = 'Lucas'     AND d.surname = 'di Grassi'     AND q.raceId = 345;
SELECT d.nationality FROM qualifying q JOIN drivers d ON q.driverId = d.driverId WHERE q.raceId = 347   AND q.q2 = '0:01:15';
SELECT d.code FROM qualifying q JOIN drivers d ON q.driverId = d.driverId WHERE q.raceId = 45   AND q.q3 LIKE '1:33%';
SELECT     r.time FROM     results AS r JOIN     drivers AS d     ON r.driverId = d.driverId WHERE     r.raceId = 743     AND d.forename = 'Bruce'     AND d.surname = 'McLaren';
SELECT     d.forename,     d.surname FROM results r JOIN drivers d     ON r.driverId = d.driverId JOIN races ra     ON r.raceId = ra.raceId WHERE     ra.name = 'San Marino Grand Prix'     AND ra.year = 2006     AND r.position = 2;
SELECT s.url FROM races r JOIN seasons s ON r.year = s.year WHERE r.raceId = 901;
SELECT COUNT(DISTINCT r.driverId) AS drivers_not_finished FROM results r JOIN races ra ON r.raceId = ra.raceId JOIN status s ON r.statusId = s.statusId WHERE ra.date = '2015-11-29'   AND s.status <> 'Finished'   AND r.time IS NOT NULL;
SELECT d.* FROM drivers d JOIN results r ON d.driverId = r.driverId WHERE r.raceId = 872   AND r.time IS NOT NULL ORDER BY d.dob DESC LIMIT 1;
SELECT      d.forename,     d.surname FROM lapTimes lt JOIN drivers d ON lt.driverId = d.driverId WHERE lt.raceId = 348 ORDER BY lt.time ASC LIMIT 1;
SELECT d.nationality FROM results r JOIN drivers d ON r.driverId = d.driverId WHERE r.fastestLapSpeed = (     SELECT MAX(fastestLapSpeed)     FROM results     WHERE fastestLapSpeed IS NOT NULL );
SELECT     CAST(         (r853.fastestLapSpeed - r854.fastestLapSpeed) * 100.0         / r853.fastestLapSpeed     AS REAL) AS percent_faster FROM     results AS r853 JOIN     drivers AS d853     ON r853.driverId = d853.driverId JOIN     results AS r854     ON r854.raceId = 854 JOIN     drivers AS d854     ON r854.driverId = d854.driverId WHERE     r853.raceId = 853     AND d853.forename = 'Paul'     AND d853.surname = 'di Resta'     AND d854.forename = 'Paul'     AND d854.surname = 'di Resta';
SELECT      CAST(COUNT(CASE WHEN r.time IS NOT NULL THEN r.driverId END) AS REAL) * 100.0 / COUNT(r.driverId) AS completion_rate FROM      results r JOIN      races ra ON r.raceId = ra.raceId WHERE      ra.date = '1983-07-16';
SELECT MIN(r.year) AS year FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE r.name = 'Singapore Grand Prix';
SELECT COUNT(*) AS race_count,        GROUP_CONCAT(name, '; ') AS race_names FROM races WHERE year = 2005 ORDER BY name DESC;
SELECT r.name FROM races r WHERE strftime('%Y', r.date) = (SELECT strftime('%Y', MIN(date)) FROM races)   AND strftime('%m', r.date) = (SELECT strftime('%m', MIN(date)) FROM races);
SELECT     r.name,     r.date FROM races AS r WHERE r.year = 1999 ORDER BY r.round DESC LIMIT 1;
SELECT year FROM races GROUP BY year ORDER BY MAX(round) DESC LIMIT 1;
SELECT r.name FROM races AS r WHERE r.year = 2017   AND r.raceId NOT IN (       SELECT r2.raceId       FROM races AS r2       WHERE r2.year = 2000   );
SELECT      c.country,     c.name AS circuit_name,     c.location FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE r.name = 'European Grand Prix' ORDER BY r.year ASC LIMIT 1;
SELECT MAX(r.year) AS last_season FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE c.name = 'Brands Hatch'   AND r.name = 'British Grand Prix';
SELECT COUNT(DISTINCT r.year) AS seasons_count FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE c.name = 'Silverstone Circuit'   AND r.name = 'British Grand Prix';
SELECT     d.forename,     d.surname FROM     driverStandings ds JOIN     drivers d ON ds.driverId = d.driverId JOIN     races r ON ds.raceId = r.raceId WHERE     r.year = 2010     AND r.name = 'Singapore Grand Prix' ORDER BY     ds.position ASC;
SELECT     d.forename,     d.surname,     ds.points FROM driverStandings AS ds JOIN drivers AS d     ON ds.driverId = d.driverId ORDER BY ds.points DESC LIMIT 1;
SELECT     d.forename,     d.surname,     r.points FROM results r JOIN drivers d ON r.driverId = d.driverId JOIN races ra ON r.raceId = ra.raceId WHERE ra.year = 2017   AND ra.name = 'Chinese Grand Prix' ORDER BY r.position ASC LIMIT 3;
SELECT      d.forename,     d.surname,     r.name FROM lapTimes lt JOIN drivers d ON lt.driverId = d.driverId JOIN races r ON lt.raceId = r.raceId WHERE lt.milliseconds = (     SELECT MIN(milliseconds)     FROM lapTimes     WHERE milliseconds IS NOT NULL );
SELECT AVG(lt.milliseconds) AS average_lap_time FROM lapTimes lt JOIN drivers d   ON lt.driverId = d.driverId JOIN races r   ON lt.raceId = r.raceId WHERE d.forename = 'Lewis'   AND d.surname = 'Hamilton'   AND r.name = 'Malaysian Grand Prix'   AND r.year = 2009;
SELECT      CAST(COUNT(CASE WHEN r.position > 1 THEN r.raceId END) AS REAL) * 100.0 / COUNT(r.raceId) AS percentage FROM results r JOIN drivers d ON r.driverId = d.driverId JOIN races ra ON r.raceId = ra.raceId WHERE d.surname = 'Hamilton'   AND ra.year >= 2010;
SELECT      d.forename,     d.surname,     d.nationality,     MAX(ds.points) AS max_points FROM      drivers d JOIN      driverStandings ds ON d.driverId = ds.driverId GROUP BY      d.driverId ORDER BY      SUM(ds.wins) DESC,     MAX(ds.points) DESC LIMIT 1;
SELECT      (strftime('%Y', 'now') - strftime('%Y', d.dob)) AS age,     d.forename || ' ' || d.surname AS name FROM      drivers d WHERE      d.nationality = 'Japanese' ORDER BY      d.dob DESC LIMIT 1;
SELECT c.circuitId FROM circuits AS c JOIN races AS r ON c.circuitId = r.circuitId WHERE r.year BETWEEN 1990 AND 2000 GROUP BY c.circuitId HAVING COUNT(r.raceId) = 4;
SELECT      c.name AS circuit_name,     c.location AS circuit_location,     r.name AS race_name FROM circuits c JOIN races r ON c.circuitId = r.circuitId WHERE c.country = 'USA'   AND r.year = 2006;
SELECT     r.name AS race_name,     c.name AS circuit_name,     c.location AS circuit_location FROM races AS r JOIN circuits AS c     ON r.circuitId = c.circuitId WHERE     strftime('%m', r.date) = '09'     AND strftime('%Y', r.date) = '2005';
SELECT DISTINCT r.name FROM results res JOIN drivers d ON res.driverId = d.driverId JOIN races r ON res.raceId = r.raceId WHERE d.forename = 'Alex'   AND d.surname = 'Yoong'   AND res.position < 20;
SELECT COUNT(*) AS wins FROM results r JOIN drivers d ON r.driverId = d.driverId JOIN races ra ON r.raceId = ra.raceId JOIN circuits c ON ra.circuitId = c.circuitId WHERE d.forename = 'Michael'   AND d.surname = 'Schumacher'   AND c.name = 'Sepang International Circuit'   AND r.points = (       SELECT MAX(r2.points)       FROM results r2       JOIN races ra2 ON r2.raceId = ra2.raceId       JOIN circuits c2 ON ra2.circuitId = c2.circuitId       WHERE c2.name = 'Sepang International Circuit'   );
SELECT     r.name AS race,     r.year AS year FROM results res JOIN drivers d     ON res.driverId = d.driverId JOIN races r     ON res.raceId = r.raceId WHERE d.forename = 'Michael'   AND d.surname = 'Schumacher'   AND res.fastestLap IS NOT NULL ORDER BY res.milliseconds ASC LIMIT 1;
SELECT AVG(r.points) AS average_points FROM results r JOIN drivers d ON r.driverId = d.driverId JOIN races ra ON r.raceId = ra.raceId WHERE d.forename = 'Eddie'   AND d.surname = 'Irvine'   AND ra.year = 2000;
SELECT     r.year,     res.points FROM     drivers d JOIN     results res ON d.driverId = res.driverId JOIN     races r ON res.raceId = r.raceId WHERE     d.forename = 'Lewis'     AND d.surname = 'Hamilton' ORDER BY     r.year ASC LIMIT 1;
SELECT     r.raceId,     r.name,     c.country FROM     races r JOIN     circuits c     ON r.circuitId = c.circuitId WHERE     r.year = 2017 ORDER BY     r.date;
SELECT     r.name AS race_name,     r.year AS year,     c.location AS circuit_location FROM results AS res JOIN races AS r     ON res.raceId = r.raceId JOIN circuits AS c     ON r.circuitId = c.circuitId GROUP BY     res.raceId,     r.name,     r.year,     c.location ORDER BY     MAX(res.laps) DESC LIMIT 1;
SELECT      CAST(SUM(CASE WHEN c.country = 'Germany' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) AS percentage FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE r.name = 'European Grand Prix';
SELECT      lat,     lng FROM      circuits WHERE      name = 'Silverstone Circuit';
SELECT name, lat FROM circuits WHERE name IN ('Silverstone Circuit', 'Hockenheimring', 'Hungaroring') ORDER BY lat DESC LIMIT 1;
SELECT circuitRef FROM circuits WHERE name = 'Marina Bay Street Circuit';
SELECT country FROM circuits ORDER BY alt DESC LIMIT 1;
SELECT COUNT(*) AS count FROM drivers WHERE code IS NULL;
SELECT d.nationality FROM drivers d ORDER BY d.dob ASC LIMIT 1;
SELECT surname FROM drivers WHERE nationality = 'Italian';
SELECT url FROM drivers WHERE forename = 'Anthony'   AND surname = 'Davidson';
SELECT driverRef FROM drivers WHERE forename = 'Lewis'   AND surname = 'Hamilton';
SELECT c.name FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE r.year = 2009   AND r.name = 'Spanish Grand Prix';
SELECT DISTINCT r.year FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE c.name = 'Silverstone Circuit';
SELECT     r.url FROM races AS r JOIN circuits AS c     ON r.circuitId = c.circuitId WHERE c.name = 'Silverstone Circuit';
SELECT     r.time FROM races AS r JOIN circuits AS c     ON r.circuitId = c.circuitId WHERE     r.year = 2010     AND c.name = 'Abu Dhabi Circuit';
SELECT COUNT(*) AS race_count FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE c.country = 'Italy';
SELECT     r.date FROM races AS r JOIN circuits AS c     ON r.circuitId = c.circuitId WHERE c.name = 'Circuit de Barcelona-Catalunya';
SELECT DISTINCT c.url FROM circuits c JOIN races r ON c.circuitId = r.circuitId WHERE r.name = 'Spanish Grand Prix'   AND r.year = 2009;
SELECT MIN(r.fastestLapTime) AS fastest_lap_time FROM results r JOIN drivers d ON r.driverId = d.driverId WHERE d.forename = 'Lewis'   AND d.surname = 'Hamilton';
SELECT     d.forename,     d.surname FROM results r JOIN drivers d     ON r.driverId = d.driverId ORDER BY     CAST(r.fastestLapSpeed AS REAL) DESC LIMIT 1;
SELECT     d.driverRef FROM     results r JOIN     races ra ON r.raceId = ra.raceId JOIN     drivers d ON r.driverId = d.driverId WHERE     ra.name = 'Canadian Grand Prix'     AND ra.year = 2007     AND r.position = 1 LIMIT 1;
SELECT DISTINCT r.name FROM races r JOIN results res ON r.raceId = res.raceId JOIN drivers d ON res.driverId = d.driverId WHERE d.forename = 'Lewis'   AND d.surname = 'Hamilton';
SELECT     r.name FROM     results AS res JOIN     drivers AS d     ON res.driverId = d.driverId JOIN     races AS r     ON res.raceId = r.raceId WHERE     d.forename = 'Lewis'     AND d.surname = 'Hamilton' ORDER BY     res.rank ASC LIMIT 1;
SELECT MAX(r.fastestLapSpeed) AS fastest_lap_speed FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.name = 'Spanish Grand Prix'   AND ra.year = 2009;
SELECT DISTINCT r.year FROM races r JOIN results res ON r.raceId = res.raceId JOIN drivers d ON res.driverId = d.driverId WHERE d.forename = 'Lewis'   AND d.surname = 'Hamilton';
SELECT     r.positionOrder FROM results AS r JOIN drivers AS d     ON r.driverId = d.driverId JOIN races AS ra     ON r.raceId = ra.raceId WHERE     d.forename = 'Lewis'     AND d.surname = 'Hamilton'     AND ra.name = 'Chinese Grand Prix'     AND ra.year = 2008;
SELECT     d.forename,     d.surname FROM results r JOIN races ra ON r.raceId = ra.raceId JOIN drivers d ON r.driverId = d.driverId JOIN circuits c ON ra.circuitId = c.circuitId WHERE ra.year = 1989   AND ra.name = 'Australian Grand Prix'   AND r.grid = 4;
SELECT COUNT(*) AS driver_count FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.year = 2008   AND ra.name = 'Australian Grand Prix'   AND r.time IS NOT NULL;
SELECT     MIN(lt.milliseconds) AS fastest_lap_milliseconds FROM lapTimes AS lt JOIN drivers AS d     ON lt.driverId = d.driverId JOIN races AS r     ON lt.raceId = r.raceId WHERE     d.forename = 'Lewis'     AND d.surname = 'Hamilton'     AND r.year = 2008     AND r.name = 'Australian Grand Prix';
SELECT     r.time FROM results AS r JOIN races AS ra ON r.raceId = ra.raceId WHERE     ra.year = 2008     AND ra.name = 'Chinese Grand Prix'     AND r.position = 2;
SELECT      d.url AS url,     r.time AS finished_time FROM      results r JOIN      drivers d ON r.driverId = d.driverId JOIN      races ra ON r.raceId = ra.raceId WHERE      ra.year = 2008     AND ra.name = 'Australian Grand Prix'     AND r.position = 1     AND r.statusId = 1     AND r.time IS NOT NULL     AND r.time LIKE '____:__:__.___' LIMIT 1;
SELECT COUNT(DISTINCT r.driverId) AS driver_count FROM results r JOIN races ra ON r.raceId = ra.raceId JOIN drivers d ON r.driverId = d.driverId WHERE ra.year = 2008   AND ra.name = 'Australian Grand Prix'   AND d.nationality = 'British';
SELECT COUNT(DISTINCT r.driverId) FROM results r JOIN races ra ON r.raceId = ra.raceId JOIN status s ON r.statusId = s.statusId WHERE ra.year = 2008   AND ra.name = 'Chinese Grand Prix'   AND s.status = 'Finished'   AND r.time IS NOT NULL   AND EXISTS (       SELECT 1       FROM results r2       WHERE r2.driverId = r.driverId   );
SELECT     SUM(r.points) AS total_points FROM results r JOIN drivers d     ON r.driverId = d.driverId WHERE d.forename = 'Lewis'   AND d.surname = 'Hamilton';
SELECT      AVG(         CAST(SUBSTR(r.fastestLapTime, 1, INSTR(r.fastestLapTime, ':') - 1) AS REAL) * 60 +         CAST(SUBSTR(r.fastestLapTime, INSTR(r.fastestLapTime, ':') + 1) AS REAL)     ) AS average_fastest_lap_time_seconds FROM      results r JOIN      drivers d ON r.driverId = d.driverId WHERE      d.forename = 'Lewis'      AND d.surname = 'Hamilton'     AND r.fastestLapTime IS NOT NULL;
SELECT      CAST(COUNT(CASE WHEN r.time IS NOT NULL THEN r.raceId END) AS REAL) * 100.0 / COUNT(r.raceId) AS rate FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.year = 2008   AND ra.name = 'Australian Grand Prix';
WITH race_info AS (     SELECT          r.raceId,         r.year     FROM races r     WHERE r.name = 'Australian Grand Prix'       AND r.year = 2008 ), champion AS (     SELECT          res.raceId,         res.driverId,         res.time AS champion_time,         res.milliseconds AS champion_ms     FROM results res     JOIN race_info ri ON res.raceId = ri.raceId     WHERE res.position = 1       AND res.time IS NOT NULL ), last_driver AS (     SELECT          res.raceId,         res.driverId,         res.milliseconds AS last_ms     FROM results res     JOIN race_info ri ON res.raceId = ri.raceId     WHERE res.positionText = 'R'       AND res.milliseconds IS NOT NULL ), calc AS (     SELECT          c.champion_ms,         l.last_ms,         (l.last_ms - c.champion_ms) AS incremental_ms     FROM champion c     JOIN last_driver l ON c.raceId = l.raceId ) SELECT      ROUND((incremental_ms * 100.0) / last_ms, 2) AS percentage_faster FROM calc;
SELECT COUNT(*) FROM circuits WHERE country = 'Australia'   AND location = 'Adelaide';
SELECT     c.lat,     c.lng FROM circuits AS c WHERE c.country = 'USA';
SELECT COUNT(*) FROM drivers WHERE nationality = 'British'   AND dob > '1980-12-31';
SELECT MAX(cr.points) AS max_points FROM constructorResults AS cr JOIN constructors AS c   ON cr.constructorId = c.constructorId WHERE c.nationality = 'British';
SELECT c.name FROM constructorStandings cs JOIN constructors c ON cs.constructorId = c.constructorId ORDER BY cs.points DESC LIMIT 1;
SELECT     c.name FROM constructorResults AS cr JOIN constructors AS c     ON cr.constructorId = c.constructorId WHERE     cr.raceId = 291     AND cr.points = 0;
SELECT COUNT(*) FROM (     SELECT         cr.constructorId     FROM constructorResults AS cr     JOIN constructors AS c         ON cr.constructorId = c.constructorId     WHERE c.nationality = 'Japanese'       AND cr.points = 0     GROUP BY cr.constructorId     HAVING COUNT(cr.raceId) = 2 ) AS sub;
SELECT DISTINCT c.name FROM constructorStandings cs JOIN constructors c ON cs.constructorId = c.constructorId WHERE cs.position = 1;
SELECT COUNT(DISTINCT c.constructorId) AS count FROM constructors c JOIN qualifying q ON c.constructorId = q.constructorId JOIN lapTimes lt ON q.raceId = lt.raceId AND q.driverId = lt.driverId WHERE c.nationality = 'France'   AND lt.lap > 50;
SELECT     CAST(         SUM(CASE WHEN r.time IS NOT NULL THEN 1 ELSE 0 END) AS REAL     ) * 100.0 / COUNT(r.driverId) AS completion_percentage FROM results r JOIN drivers d ON r.driverId = d.driverId JOIN races ra ON r.raceId = ra.raceId WHERE d.nationality = 'Japanese'   AND ra.year BETWEEN 2007 AND 2009;
SELECT     r.year,     AVG(         CAST(SUBSTR(res.time, 1, INSTR(res.time, ':') - 1) AS REAL) * 3600 +         CAST(SUBSTR(res.time, INSTR(res.time, ':') + 1, INSTR(SUBSTR(res.time, INSTR(res.time, ':') + 1), ':') - 1) AS REAL) * 60 +         CAST(SUBSTR(res.time, INSTR(res.time, ':') + 1 + INSTR(SUBSTR(res.time, INSTR(res.time, ':') + 1), ':')) AS REAL)     ) AS average_time_seconds FROM results res JOIN races r     ON res.raceId = r.raceId WHERE res.position = 1   AND res.time IS NOT NULL   AND r.year < 1975 GROUP BY r.year;
SELECT DISTINCT     d.forename,     d.surname FROM drivers d JOIN driverStandings ds     ON d.driverId = ds.driverId WHERE strftime('%Y', d.dob) > '1975'   AND ds.position = 2;
SELECT COUNT(*) FROM results r JOIN drivers d ON r.driverId = d.driverId WHERE d.nationality = 'Italian'   AND r.time IS NULL;
SELECT      d.forename,     d.surname FROM      results r JOIN      drivers d ON r.driverId = d.driverId WHERE      r.fastestLap = 1 ORDER BY      r.fastestLapTime ASC LIMIT 1;
SELECT     r.fastestLap FROM     results r JOIN     races ra ON r.raceId = ra.raceId WHERE     ra.year = 2009     AND r.position = 1     AND r.time IS NOT NULL     AND r.time LIKE '%:%:%.%';
SELECT AVG(r.fastestLapSpeed) FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.name = 'Spanish Grand Prix'   AND ra.year = 2009;
SELECT     r.name,     r.year FROM results AS res JOIN races AS r     ON res.raceId = r.raceId WHERE res.milliseconds IS NOT NULL ORDER BY res.milliseconds ASC LIMIT 1;
SELECT     CAST(         SUM(CASE WHEN CAST(strftime('%Y', d.dob) AS INTEGER) < 1985 AND r.laps > 50 THEN 1 ELSE 0 END) AS REAL     ) * 100.0 / COUNT(r.driverId) AS percentage FROM results r JOIN races ra ON r.raceId = ra.raceId JOIN drivers d ON r.driverId = d.driverId WHERE ra.year BETWEEN 2000 AND 2005;
SELECT COUNT(*) FROM lapTimes AS lt JOIN drivers AS d   ON lt.driverId = d.driverId WHERE d.nationality = 'French'   AND lt.milliseconds < 120000;
SELECT code FROM drivers WHERE nationality = 'America';
SELECT raceId FROM races WHERE year = 2009;
SELECT COUNT(DISTINCT driverId) AS driver_count FROM results WHERE raceId = 18;
WITH YoungestDrivers AS (     SELECT          d.driverId,         d.number,         d.nationality,         d.dob,         ROW_NUMBER() OVER (ORDER BY d.dob DESC) AS rn     FROM drivers d ) SELECT      yd.number,     SUM(CASE WHEN yd.nationality = 'Dutch' THEN 1 ELSE 0 END) AS dutch_count FROM YoungestDrivers yd WHERE yd.rn <= 3;
SELECT driverRef FROM drivers WHERE forename = 'Robert' AND surname = 'Kubica';
SELECT COUNT(*) FROM drivers WHERE nationality = 'British'   AND strftime('%Y', dob) = '1980';
SELECT     d.forename,     d.surname,     MIN(lt.time) AS earliest_lap_time FROM drivers d JOIN lapTimes lt     ON d.driverId = lt.driverId WHERE d.nationality = 'German'   AND strftime('%Y', d.dob) BETWEEN '1980' AND '1990' GROUP BY d.driverId, d.forename, d.surname ORDER BY earliest_lap_time ASC LIMIT 3;
SELECT     d.driverRef FROM     drivers AS d WHERE     d.nationality = 'German' ORDER BY     d.dob ASC LIMIT 1;
SELECT     d.driverId,     d.code FROM drivers AS d JOIN results AS r     ON d.driverId = r.driverId WHERE strftime('%Y', d.dob) = '1971'   AND r.fastestLapTime IS NOT NULL;
SELECT     d.driverId,     d.forename,     d.surname,     d.dob,     d.nationality,     lt.time AS latest_lap_time FROM     drivers d JOIN     lapTimes lt     ON d.driverId = lt.driverId WHERE     d.nationality = 'Spanish'     AND strftime('%Y', d.dob) < '1982' ORDER BY     lt.time DESC LIMIT 10;
SELECT     r.year FROM     results AS res JOIN     races AS r     ON res.raceId = r.raceId WHERE     res.fastestLapTime IS NOT NULL ORDER BY     res.fastestLapTime ASC LIMIT 1;
SELECT     r.year FROM     races r JOIN     lapTimes lt ON r.raceId = lt.raceId GROUP BY     r.year ORDER BY     MAX(lt.milliseconds) DESC LIMIT 1;
SELECT     driverId FROM     lapTimes WHERE     lap = 1 ORDER BY     time ASC LIMIT 5;
SELECT COUNT(*) AS disqualified_finishers FROM results r JOIN status s ON r.statusId = s.statusId WHERE r.raceId > 50   AND r.raceId < 100   AND s.statusId = 2   AND r.time IS NOT NULL;
SELECT      COUNT(*) AS times_held,     c.location,     c.lat,     c.lng FROM circuits c WHERE c.country = 'Austria';
SELECT r.raceId FROM results res JOIN races r ON res.raceId = r.raceId WHERE res.time IS NOT NULL GROUP BY r.raceId ORDER BY COUNT(*) DESC LIMIT 1;
SELECT     d.driverRef,     d.nationality,     d.dob FROM qualifying q JOIN drivers d     ON q.driverId = d.driverId WHERE q.raceId = 23   AND q.q2 IS NOT NULL;
WITH YoungestDriver AS (     SELECT          d.driverId,         d.forename,         d.surname,         d.dob     FROM drivers d     WHERE d.dob IS NOT NULL     ORDER BY d.dob DESC     LIMIT 1 ), FirstQualifyingRace AS (     SELECT          q.raceId,         r.year,         r.name,         r.date,         r.time     FROM qualifying q     JOIN races r ON q.raceId = r.raceId     WHERE q.driverId = (SELECT driverId FROM YoungestDriver)     ORDER BY r.date ASC     LIMIT 1 ) SELECT      fqr.year,     fqr.name,     fqr.date,     fqr.time FROM FirstQualifyingRace fqr;
SELECT COUNT(*) FROM drivers d JOIN results r ON d.driverId = r.driverId JOIN status s ON r.statusId = s.statusId WHERE d.nationality = 'American'   AND s.status = 'Puncture';
SELECT     c.url FROM constructors AS c JOIN constructorStandings AS cs     ON c.constructorId = cs.constructorId WHERE c.nationality = 'Italian' ORDER BY cs.points DESC LIMIT 1;
SELECT c.url FROM constructors c JOIN constructorStandings cs ON c.constructorId = cs.constructorId GROUP BY c.constructorId ORDER BY SUM(cs.wins) DESC LIMIT 1;
SELECT     d.forename,     d.surname FROM     lapTimes lt JOIN     drivers d     ON lt.driverId = d.driverId JOIN     races r     ON lt.raceId = r.raceId WHERE     r.name = 'French Grand Prix'     AND lt.lap = 3 ORDER BY     lt.milliseconds DESC LIMIT 1;
SELECT      r.raceId,     lt.milliseconds FROM lapTimes lt JOIN races r ON lt.raceId = r.raceId WHERE lt.lap = 1 ORDER BY lt.milliseconds ASC LIMIT 1;
SELECT AVG(r.fastestLapTime) AS avg_fastest_lap_time FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.year = 2006   AND ra.name = 'United States Grand Prix'   AND r.rank < 11;
WITH german_drivers AS (     SELECT          d.driverId,         d.forename,         d.surname     FROM drivers d     WHERE d.nationality = 'German'       AND strftime('%Y', d.dob) > '1980'       AND strftime('%Y', d.dob) < '1985' ), pit_stop_durations AS (     SELECT          ps.driverId,         ps.milliseconds AS duration_ms     FROM pitStops ps     INNER JOIN german_drivers gd ON ps.driverId = gd.driverId     WHERE ps.milliseconds IS NOT NULL ), avg_pit_stop AS (     SELECT          psd.driverId,         AVG(psd.duration_ms) AS avg_duration     FROM pit_stop_durations psd     GROUP BY psd.driverId ) SELECT      gd.forename,     gd.surname FROM german_drivers gd INNER JOIN avg_pit_stop aps ON gd.driverId = aps.driverId ORDER BY aps.avg_duration ASC LIMIT 3;
SELECT      r.time FROM      results r JOIN      races ra ON r.raceId = ra.raceId WHERE      ra.name = 'Canadian Grand Prix'     AND ra.year = 2008     AND r.position = 1;
SELECT      c.constructorRef,     c.url FROM      results r JOIN      races ra ON r.raceId = ra.raceId JOIN      constructors c ON r.constructorId = c.constructorId WHERE      ra.year = 2009     AND ra.name = 'Singapore Grand Prix'     AND r.position = 1 ORDER BY      r.milliseconds DESC LIMIT 1;
SELECT     d.forename,     d.surname,     d.dob FROM     drivers AS d WHERE     d.nationality = 'Austrian'     AND strftime('%Y', d.dob) BETWEEN '1981' AND '1991';
SELECT     d.forename || ' ' || d.surname AS full_name,     d.url AS wiki_page_link,     d.dob AS date_of_birth FROM     drivers AS d WHERE     d.nationality = 'German'     AND strftime('%Y', d.dob) BETWEEN '1971' AND '1985' ORDER BY     d.dob DESC;
SELECT      location,     country,     lat,     lng FROM      circuits WHERE      name = 'Hungaroring';
SELECT     cr.points AS score,     c.name AS name,     c.nationality AS nationality FROM constructorResults cr JOIN constructors c     ON cr.constructorId = c.constructorId JOIN races r     ON cr.raceId = r.raceId WHERE r.name = 'Monaco Grand Prix'   AND r.year BETWEEN 1980 AND 2010 ORDER BY cr.points DESC LIMIT 1;
SELECT AVG(r.points) AS average_score FROM results r JOIN drivers d ON r.driverId = d.driverId JOIN races ra ON r.raceId = ra.raceId WHERE d.forename = 'Lewis'   AND d.surname = 'Hamilton'   AND ra.name LIKE '%Turkish Grand Prix%';
SELECT AVG(races_per_year) AS annual_average_races FROM (     SELECT COUNT(*) AS races_per_year     FROM races     WHERE date BETWEEN '2000-01-01' AND '2010-12-31'     GROUP BY year );
SELECT nationality FROM drivers GROUP BY nationality ORDER BY COUNT(*) DESC LIMIT 1;
SELECT COUNT(*) AS victories FROM driverStandings WHERE position = 91;
SELECT r.name FROM results AS res JOIN races AS r ON res.raceId = r.raceId WHERE res.fastestLapTime IS NOT NULL ORDER BY res.fastestLapTime ASC LIMIT 1;
SELECT      c.location || ', ' || c.country AS full_location FROM      races r JOIN      circuits c ON r.circuitId = c.circuitId ORDER BY      r.date DESC LIMIT 1;
SELECT      d.forename,     d.surname FROM qualifying q JOIN races r ON q.raceId = r.raceId JOIN circuits c ON r.circuitId = c.circuitId JOIN drivers d ON q.driverId = d.driverId WHERE c.name = 'Marina Bay Street Circuit'   AND r.year = 2008   AND q.raceId = (       SELECT r2.raceId       FROM races r2       JOIN circuits c2 ON r2.circuitId = c2.circuitId       WHERE c2.name = 'Marina Bay Street Circuit'         AND r2.year = 2008       ORDER BY r2.round       LIMIT 1 OFFSET 2   ) ORDER BY q.q3 ASC LIMIT 1;
WITH YoungestDriver AS (     SELECT          d.driverId,         d.forename,         d.surname,         d.nationality,         d.dob     FROM drivers d     WHERE d.dob = (SELECT MAX(dob) FROM drivers) ), FirstRace AS (     SELECT          yd.driverId,         MIN(r.raceId) AS firstRaceId     FROM YoungestDriver yd     JOIN results res ON yd.driverId = res.driverId     JOIN races r ON res.raceId = r.raceId     GROUP BY yd.driverId ) SELECT      yd.forename || ' ' || yd.surname AS full_name,     yd.nationality,     r.name AS first_race_name FROM YoungestDriver yd JOIN FirstRace fr ON yd.driverId = fr.driverId JOIN races r ON fr.firstRaceId = r.raceId;
SELECT COUNT(*) AS accident_count FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.name = 'Canadian Grand Prix'   AND r.statusId = 3   AND r.driverId = (       SELECT r2.driverId       FROM results r2       JOIN races ra2 ON r2.raceId = ra2.raceId       WHERE ra2.name = 'Canadian Grand Prix'         AND r2.statusId = 3       GROUP BY r2.driverId       ORDER BY COUNT(*) DESC       LIMIT 1   );
SELECT     ds.wins,     d.forename,     d.surname FROM driverStandings AS ds JOIN drivers AS d   ON ds.driverId = d.driverId WHERE d.dob = (     SELECT MIN(dob)     FROM drivers     WHERE dob IS NOT NULL );
SELECT MAX(duration) AS longest_time FROM pitStops;
SELECT MIN(milliseconds) AS fastest_time FROM lapTimes;
SELECT MAX(ps.duration) AS longest_time FROM pitStops ps JOIN drivers d ON ps.driverId = d.driverId WHERE d.forename = 'Lewis'   AND d.surname = 'Hamilton';
SELECT     ps.lap FROM pitStops AS ps JOIN drivers AS d     ON ps.driverId = d.driverId JOIN races AS r     ON ps.raceId = r.raceId WHERE     d.forename = 'Lewis'     AND d.surname = 'Hamilton'     AND r.year = 2011     AND r.name = 'Australian Grand Prix';
SELECT     ps.duration FROM pitStops AS ps JOIN races AS r     ON ps.raceId = r.raceId WHERE r.year = 2011   AND r.name = 'Australian Grand Prix';
SELECT     MIN(lt.time) AS lap_record FROM lapTimes AS lt JOIN drivers AS d     ON lt.driverId = d.driverId WHERE     d.forename = 'Lewis'     AND d.surname = 'Hamilton';
SELECT      d.forename,     d.surname FROM lapTimes lt JOIN drivers d ON lt.driverId = d.driverId ORDER BY lt.milliseconds ASC LIMIT 1;
SELECT     c.position FROM     circuits AS c JOIN     races AS r ON c.circuitId = r.circuitId JOIN     results AS res ON r.raceId = res.raceId JOIN     drivers AS d ON res.driverId = d.driverId WHERE     d.forename = 'Lewis'     AND d.surname = 'Hamilton'     AND res.fastestLap IS NOT NULL     AND res.fastestLapTime = (         SELECT MIN(res2.fastestLapTime)         FROM             results AS res2         JOIN             drivers AS d2 ON res2.driverId = d2.driverId         WHERE             d2.forename = 'Lewis'             AND d2.surname = 'Hamilton'             AND res2.fastestLap IS NOT NULL     );
SELECT MIN(lt.time) AS lap_record FROM lapTimes lt JOIN races r ON lt.raceId = r.raceId JOIN circuits c ON r.circuitId = c.circuitId WHERE c.name = 'Austrian Grand Prix Circuit';
SELECT     c.name AS circuit_name,     lt.time AS lap_record FROM lapTimes lt JOIN races r ON lt.raceId = r.raceId JOIN circuits c ON r.circuitId = c.circuitId WHERE c.country = 'Italy' ORDER BY lt.milliseconds ASC LIMIT 1;
SELECT     r.name FROM     lapTimes AS lt JOIN     races AS r     ON lt.raceId = r.raceId JOIN     circuits AS c     ON r.circuitId = c.circuitId WHERE     c.name = 'Austrian Grand Prix Circuit' ORDER BY     lt.milliseconds ASC LIMIT 1;
WITH lap_record AS (     SELECT         lt.raceId,         lt.driverId,         lt.time AS lap_time,         lt.milliseconds AS lap_ms     FROM lapTimes lt     JOIN circuits c ON lt.raceId = (         SELECT r.raceId         FROM races r         WHERE r.circuitId = c.circuitId     )     WHERE c.name = 'Austrian Grand Prix Circuit'     ORDER BY lt.milliseconds ASC     LIMIT 1 ) SELECT     ps.duration FROM pitStops ps JOIN lap_record lr ON ps.raceId = lr.raceId AND ps.driverId = lr.driverId;
SELECT DISTINCT     c.lat,     c.lng FROM circuits AS c JOIN races AS r     ON c.circuitId = r.circuitId JOIN lapTimes AS lt     ON r.raceId = lt.raceId WHERE lt.time = '1:29.488'   AND lt.milliseconds = (       SELECT MIN(lt2.milliseconds)       FROM lapTimes AS lt2       JOIN races AS r2           ON lt2.raceId = r2.raceId       WHERE r2.circuitId = c.circuitId   );
SELECT AVG(ps.milliseconds) FROM pitStops ps JOIN drivers d ON ps.driverId = d.driverId WHERE d.forename = 'Lewis'   AND d.surname = 'Hamilton';
SELECT AVG(lt.milliseconds) FROM lapTimes AS lt JOIN races AS r ON lt.raceId = r.raceId JOIN circuits AS c ON r.circuitId = c.circuitId WHERE c.country = 'Italy';
SELECT     p.player_api_id FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id ORDER BY     pa.overall_rating DESC LIMIT 1;
SELECT     p.height,     p.player_name FROM Player AS p ORDER BY p.height DESC LIMIT 1;
SELECT     pa.preferred_foot FROM Player_Attributes AS pa ORDER BY     pa.potential ASC LIMIT 1;
SELECT COUNT(*) FROM Player_Attributes WHERE overall_rating >= 60   AND overall_rating < 65   AND defensive_work_rate = 'low';
SELECT      p.player_api_id FROM      Player p JOIN      Player_Attributes pa ON p.player_api_id = pa.player_api_id GROUP BY      p.player_api_id ORDER BY      MAX(pa.crossing) DESC LIMIT 5;
SELECT     l.name FROM Match AS m JOIN League AS l     ON m.league_id = l.id WHERE m.season = '2015/2016' GROUP BY     l.id,     l.name ORDER BY     SUM(m.home_team_goal + m.away_team_goal) DESC LIMIT 1;
SELECT     t.team_long_name FROM Match AS m JOIN Team AS t     ON m.home_team_api_id = t.team_api_id WHERE     m.season = '2015/2016'     AND m.home_team_goal < m.away_team_goal GROUP BY     t.team_long_name ORDER BY     COUNT(*) ASC LIMIT 1;
SELECT     p.player_name FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id ORDER BY     pa.penalties DESC LIMIT 10;
SELECT     T.team_long_name FROM     Match AS M JOIN     League AS L     ON M.league_id = L.id JOIN     Team AS T     ON M.away_team_api_id = T.team_api_id WHERE     L.name = 'Scotland Premier League'     AND M.season = '2009/2010'     AND M.away_team_goal > M.home_team_goal GROUP BY     T.team_long_name ORDER BY     COUNT(*) DESC LIMIT 1;
SELECT     buildUpPlaySpeed FROM     Team_Attributes ORDER BY     buildUpPlaySpeed DESC LIMIT 4;
SELECT     l.name FROM     Match m JOIN     League l     ON m.league_id = l.id WHERE     m.season = '2015/2016' GROUP BY     l.name ORDER BY     SUM(CASE WHEN m.home_team_goal = m.away_team_goal THEN 1 ELSE 0 END) DESC LIMIT 1;
SELECT     p.player_name,     CAST((julianday('now') - julianday(p.birthday)) / 365.25 AS INTEGER) AS age FROM Player p JOIN Player_Attributes pa     ON p.player_api_id = pa.player_api_id WHERE pa.sprint_speed >= 97   AND strftime('%Y', pa.date) >= '2013'   AND strftime('%Y', pa.date) <= '2015';
SELECT      l.name,     COUNT(m.league_id) AS match_count FROM      League l JOIN      Match m ON l.id = m.league_id GROUP BY      l.id, l.name ORDER BY      match_count DESC LIMIT 1;
SELECT      SUM(height) * 1.0 / COUNT(id) AS average_height FROM      Player WHERE      birthday >= '1990-01-01 00:00:00'      AND birthday < '1996-01-01 00:00:00';
SELECT     player_api_id FROM     Player_Attributes WHERE     substr(date, 1, 4) = '2010'     AND overall_rating = (         SELECT MAX(overall_rating)         FROM Player_Attributes         WHERE substr(date, 1, 4) = '2010'     );
SELECT     team_fifa_api_id FROM Team_Attributes WHERE buildUpPlaySpeed > 50   AND buildUpPlaySpeed < 60;
WITH AvgBuildUp AS (     SELECT          AVG(ta.buildUpPlayPassing) AS avg_buildUpPlayPassing     FROM Team_Attributes ta     WHERE strftime('%Y', ta.date) = '2012'       AND ta.buildUpPlayPassing IS NOT NULL ) SELECT DISTINCT t.team_long_name FROM Team t JOIN Team_Attributes ta ON t.team_api_id = ta.team_api_id CROSS JOIN AvgBuildUp ab WHERE strftime('%Y', ta.date) = '2012'   AND ta.buildUpPlayPassing IS NOT NULL   AND ta.buildUpPlayPassing > ab.avg_buildUpPlayPassing;
SELECT     CAST(SUM(CASE WHEN pa.preferred_foot = 'left' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(p.player_fifa_api_id) AS percentage FROM Player p JOIN Player_Attributes pa     ON p.player_fifa_api_id = pa.player_fifa_api_id WHERE strftime('%Y', p.birthday) BETWEEN '1987' AND '1992';
SELECT     l.name AS league_name,     SUM(m.home_team_goal + m.away_team_goal) AS total_goals FROM League l JOIN Match m ON l.id = m.league_id GROUP BY l.id, l.name ORDER BY total_goals ASC LIMIT 5;
SELECT     CAST(SUM(pa.long_shots) AS REAL) / COUNT(pa.player_fifa_api_id) AS average_long_shots FROM Player_Attributes pa JOIN Player p     ON pa.player_fifa_api_id = p.player_fifa_api_id WHERE p.player_name = 'Ahmed Samir Farag';
SELECT     p.player_name FROM Player AS p JOIN Player_Attributes AS pa     ON p.player_fifa_api_id = pa.player_fifa_api_id WHERE p.height > 180 GROUP BY     p.player_name ORDER BY     SUM(pa.heading_accuracy) * 1.0 / COUNT(pa.player_fifa_api_id) DESC LIMIT 10;
WITH TeamAttributes2014 AS (     SELECT         ta.team_api_id,         ta.chanceCreationPassing     FROM Team_Attributes ta     WHERE ta.buildUpPlayDribblingClass = 'Normal'       AND ta.date >= '2014-01-01 00:00:00'       AND ta.date <= '2014-01-31 00:00:00' ), AverageChanceCreation AS (     SELECT         AVG(chanceCreationPassing) AS avg_chance_creation     FROM TeamAttributes2014 ) SELECT     t.team_long_name FROM Team t JOIN TeamAttributes2014 ta ON t.team_api_id = ta.team_api_id CROSS JOIN AverageChanceCreation acc WHERE ta.chanceCreationPassing < acc.avg_chance_creation ORDER BY ta.chanceCreationPassing DESC;
SELECT     L.name FROM League AS L JOIN Match AS M     ON L.id = M.league_id WHERE     M.season = '2009/2010' GROUP BY     L.id,     L.name HAVING     SUM(M.home_team_goal) / COUNT(DISTINCT M.id) > SUM(M.away_team_goal) / COUNT(DISTINCT M.id);
SELECT team_short_name FROM Team WHERE team_long_name = 'Queens Park Rangers';
SELECT     p.player_name FROM     Player AS p WHERE     substr(p.birthday, 1, 4) = '1970'     AND substr(p.birthday, 6, 2) = '10';
SELECT     pa.attacking_work_rate FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Franco Zennaro';
SELECT     ta.buildUpPlayPositioningClass FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE t.team_long_name = 'ADO Den Haag';
SELECT     pa.heading_accuracy FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     p.player_name = 'Francois Affolter'     AND pa.date = '2014-09-18 00:00:00';
SELECT     pa.overall_rating FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     p.player_name = 'Gabriel Tamas'     AND strftime('%Y', pa.date) = '2011';
SELECT COUNT(*) AS match_count FROM Match m JOIN League l ON m.league_id = l.id WHERE m.season = '2015/2016'   AND l.name = 'Scotland Premier League';
SELECT     pa.preferred_foot FROM Player AS p JOIN Player_Attributes AS pa     ON p.player_api_id = pa.player_api_id ORDER BY p.birthday DESC LIMIT 1;
SELECT     p.player_name FROM Player AS p JOIN Player_Attributes AS pa     ON p.player_api_id = pa.player_api_id WHERE pa.potential = (     SELECT MAX(potential)     FROM Player_Attributes );
SELECT COUNT(*) AS count FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.weight < 130   AND pa.preferred_foot = 'left';
SELECT DISTINCT T.team_short_name FROM Team T JOIN Team_Attributes TA ON T.team_api_id = TA.team_api_id WHERE TA.chanceCreationPassingClass = 'Risky';
SELECT     pa.defensive_work_rate FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     p.player_name = 'David Wilson';
SELECT     p.birthday FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id ORDER BY     pa.overall_rating DESC LIMIT 1;
SELECT l.name FROM League AS l JOIN Country AS c ON l.country_id = c.id WHERE c.name = 'Netherlands';
SELECT AVG(m.home_team_goal) AS average_home_team_goal FROM Match m JOIN Country c ON m.country_id = c.id WHERE c.name = 'Poland'   AND m.season = '2010/2011';
WITH HeightRange AS (     SELECT         MIN(height) AS min_height,         MAX(height) AS max_height     FROM Player ), PlayersInRange AS (     SELECT         p.player_name,         pa.finishing     FROM Player p     JOIN Player_Attributes pa         ON p.player_api_id = pa.player_api_id     CROSS JOIN HeightRange hr     WHERE p.height BETWEEN hr.min_height AND hr.max_height ), AvgFinishing AS (     SELECT         player_name,         AVG(finishing) AS avg_finishing     FROM PlayersInRange     GROUP BY player_name ) SELECT     player_name FROM AvgFinishing ORDER BY avg_finishing DESC LIMIT 1;
SELECT player_name FROM Player WHERE height > 180;
SELECT COUNT(*) AS player_count FROM Player WHERE strftime('%Y', birthday) > '1990';
SELECT COUNT(*) FROM Player WHERE player_name LIKE 'Adam%'   AND weight > 170;
SELECT DISTINCT p.player_name FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE pa.overall_rating > 80   AND strftime('%Y', pa.date) BETWEEN '2008' AND '2010';
SELECT pa.potential FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.player_name = 'Aaron Doran';
SELECT * FROM Player_Attributes WHERE preferred_foot = 'left';
SELECT T.team_long_name FROM Team AS T JOIN Team_Attributes AS TA   ON T.team_api_id = TA.team_api_id WHERE TA.buildUpPlaySpeedClass = 'Fast';
SELECT     ta.buildUpPlayPassingClass FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE t.team_short_name = 'CLB';
SELECT     T.team_short_name FROM Team_Attributes AS TA JOIN Team AS T     ON TA.team_api_id = T.team_api_id WHERE     TA.buildUpPlayPassing > 70;
SELECT     SUM(pa.overall_rating) / COUNT(pa.id) AS average_overall_rating FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     strftime('%Y', pa.date) >= '2010'     AND strftime('%Y', pa.date) <= '2015'     AND p.height > 170;
SELECT player_name FROM Player ORDER BY height ASC LIMIT 1;
SELECT c.name FROM League l JOIN Country c ON l.country_id = c.id WHERE l.name = 'Italy Serie A';
SELECT     t.team_short_name FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE     ta.buildUpPlaySpeed = 31     AND ta.buildUpPlayDribbling = 53     AND ta.buildUpPlayPassing = 32;
SELECT AVG(pa.overall_rating) AS average_overall_rating FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Aaron Doran';
SELECT COUNT(*) AS match_count FROM Match AS m JOIN League AS l   ON m.league_id = l.id WHERE l.name = 'Germany 1. Bundesliga'   AND strftime('%Y-%m', m.date) BETWEEN '2008-08' AND '2008-10';
SELECT T.team_short_name FROM Team AS T JOIN Match AS M ON T.team_api_id = M.home_team_api_id WHERE M.home_team_goal = 10;
SELECT     p.player_name FROM Player AS p JOIN Player_Attributes AS pa     ON p.player_api_id = pa.player_api_id WHERE pa.potential = 61   AND pa.balance = (       SELECT MAX(balance)       FROM Player_Attributes       WHERE potential = 61   );
SELECT      AVG(CASE WHEN p.player_name = 'Abdou Diallo' THEN pa.ball_control ELSE NULL END) -     AVG(CASE WHEN p.player_name = 'Aaron Appindangoye' THEN pa.ball_control ELSE NULL END) AS difference FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name IN ('Abdou Diallo', 'Aaron Appindangoye');
SELECT team_long_name FROM Team WHERE team_short_name = 'GEN';
SELECT      p1.player_name AS older_player FROM Player p1 JOIN Player p2 ON p1.player_name = 'Aaron Lennon' AND p2.player_name = 'Abdelaziz Barrada' WHERE p1.birthday < p2.birthday UNION ALL SELECT      p2.player_name AS older_player FROM Player p1 JOIN Player p2 ON p1.player_name = 'Aaron Lennon' AND p2.player_name = 'Abdelaziz Barrada' WHERE p2.birthday < p1.birthday;
SELECT player_name FROM Player ORDER BY height DESC LIMIT 1;
SELECT COUNT(*) FROM Player_Attributes WHERE preferred_foot = 'left'   AND attacking_work_rate = 'low';
SELECT c.name FROM League l JOIN Country c ON l.country_id = c.id WHERE l.name = 'Belgium Jupiler League';
SELECT L.name FROM League AS L JOIN Country AS C ON L.country_id = C.id WHERE C.name = 'Germany';
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id ORDER BY pa.overall_rating DESC LIMIT 1;
SELECT COUNT(DISTINCT pa.player_api_id) AS player_count FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE strftime('%Y', p.birthday) < '1986'   AND pa.defensive_work_rate = 'high';
SELECT     p.player_name,     MAX(pa.crossing) AS max_crossing FROM Player p JOIN Player_Attributes pa     ON p.player_api_id = pa.player_api_id WHERE p.player_name IN ('Alexis', 'Ariel Borysiuk', 'Arouna Kone') GROUP BY p.player_name ORDER BY max_crossing DESC LIMIT 1;
SELECT     pa.heading_accuracy FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     p.player_name = 'Ariel Borysiuk';
SELECT COUNT(*) FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.height > 180   AND pa.volleys > 70;
SELECT     p.player_name FROM Player AS p JOIN Player_Attributes AS pa     ON p.player_api_id = pa.player_api_id WHERE     pa.volleys > 70     AND pa.dribbling > 70;
SELECT COUNT(*) FROM Match AS m JOIN Country AS c ON m.country_id = c.id WHERE c.name = 'Belgium'   AND m.season = '2008/2009';
SELECT     pa.long_passing FROM Player p JOIN Player_Attributes pa     ON p.player_api_id = pa.player_api_id ORDER BY     p.birthday ASC LIMIT 1;
SELECT COUNT(*) FROM Match AS m JOIN League AS l ON m.league_id = l.id WHERE l.name = 'Belgium Jupiler League'   AND SUBSTR(m.date, 1, 7) = '2009-04';
SELECT l.name FROM League l JOIN Match m ON l.id = m.league_id WHERE m.season = '2008/2009' GROUP BY l.id, l.name ORDER BY COUNT(m.id) DESC LIMIT 1;
SELECT      CAST(SUM(pa.overall_rating) AS REAL) / COUNT(pa.id) AS average_overall_rating FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE strftime('%Y', p.birthday) < '1986';
SELECT      (         (             (                 SELECT pa.overall_rating                 FROM Player_Attributes pa                 JOIN Player p ON pa.player_api_id = p.player_api_id                 WHERE p.player_name = 'Ariel Borysiuk'             )             -             (                 SELECT pa.overall_rating                 FROM Player_Attributes pa                 JOIN Player p ON pa.player_api_id = p.player_api_id                 WHERE p.player_name = 'Paulin Puel'             )         )         /         (             SELECT pa.overall_rating             FROM Player_Attributes pa             JOIN Player p ON pa.player_api_id = p.player_api_id             WHERE p.player_name = 'Paulin Puel'         )     ) * 100 AS percentage_difference;
SELECT AVG(T1.buildUpPlaySpeed) AS average_build_up_play_speed FROM Team_Attributes AS T1 INNER JOIN Team AS T2   ON T1.team_api_id = T2.team_api_id WHERE T2.team_long_name = 'Heart of Midlothian';
SELECT AVG(pa.overall_rating) AS average_overall_rating FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Pietro Marino';
SELECT     SUM(pa.crossing) AS total_crossing_score FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     p.player_name = 'Aaron Lennox';
SELECT     MAX(T1.chanceCreationPassing) AS highest_chance_creation_passing,     T1.chanceCreationPassingClass AS chance_creation_passing_class FROM Team_Attributes AS T1 INNER JOIN Team AS T2     ON T1.team_api_id = T2.team_api_id WHERE     T2.team_long_name = 'Ajax' ORDER BY     T1.chanceCreationPassing DESC LIMIT 1;
SELECT     pa.preferred_foot FROM Player AS p JOIN Player_Attributes AS pa     ON p.player_api_id = pa.player_api_id WHERE p.player_name = 'Abdou Diallo';
SELECT MAX(pa.overall_rating) AS highest_overall_rating FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Dorlan Pabon';
SELECT AVG(m.away_team_goal) AS average_goals FROM Match m JOIN Team t ON m.away_team_api_id = t.team_api_id JOIN Country c ON m.country_id = c.id WHERE t.team_long_name = 'Parma'   AND c.name = 'Italy';
SELECT p.player_name FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE pa.overall_rating = 77   AND pa.date LIKE '2016-06-23%' ORDER BY p.birthday ASC LIMIT 1;
SELECT     pa.overall_rating FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     p.player_name = 'Aaron Mooy'     AND pa.date LIKE '2016-02-04%';
SELECT     pa.potential FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     p.player_name = 'Francesco Parravicini'     AND pa.date = '2010-08-30 00:00:00';
SELECT     pa.attacking_work_rate FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     p.player_name = 'Francesco Migliore'     AND pa.date LIKE '2015-05-01%';
SELECT     pa.defensive_work_rate FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     p.player_name = 'Kevin Berigaud'     AND pa.date = '2013-02-22 00:00:00';
SELECT     pa.date FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     p.player_name = 'Kevin Constant'     AND pa.crossing = (         SELECT MAX(pa2.crossing)         FROM Player_Attributes AS pa2         JOIN Player AS p2             ON pa2.player_api_id = p2.player_api_id         WHERE             p2.player_name = 'Kevin Constant'     ) ORDER BY     pa.date ASC LIMIT 1;
SELECT     ta.buildUpPlaySpeedClass FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE     t.team_long_name = 'Willem II'     AND ta.date = '2012-02-22';
SELECT     ta.buildUpPlayDribblingClass FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE     t.team_short_name = 'LEI'     AND ta.date = '2015-09-10 00:00:00';
SELECT     ta.buildUpPlayPassingClass FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE     t.team_long_name = 'FC Lorient'     AND ta.date LIKE '2010-02-22%';
SELECT     ta.chanceCreationPassingClass FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE     t.team_long_name = 'PEC Zwolle'     AND ta.date = '2013-09-20 00:00:00';
SELECT     ta.chanceCreationCrossingClass FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE     t.team_long_name = 'Hull City'     AND ta.date = '2010-02-22 00:00:00';
SELECT     ta.defenceAggressionClass FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE     t.team_long_name = 'Hannover 96'     AND ta.date LIKE '2015-09-10%';
SELECT     AVG(pa.overall_rating) AS average_overall_rating FROM Player_Attributes pa JOIN Player p     ON pa.player_api_id = p.player_api_id WHERE     p.player_name = 'Marko Arnautovic'     AND substr(pa.date, 1, 10) BETWEEN '2007-02-22' AND '2016-04-21';
SELECT      (         (             SELECT pa.overall_rating             FROM Player_Attributes pa             JOIN Player p ON pa.player_api_id = p.player_api_id             WHERE p.player_name = 'Landon Donovan'               AND pa.date = '2013-07-12'         )         -         (             SELECT pa.overall_rating             FROM Player_Attributes pa             JOIN Player p ON pa.player_api_id = p.player_api_id             WHERE p.player_name = 'Jordan Bowery'               AND pa.date = '2013-07-12'         )     ) * 100.0 /     (         SELECT pa.overall_rating         FROM Player_Attributes pa         JOIN Player p ON pa.player_api_id = p.player_api_id         WHERE p.player_name = 'Landon Donovan'           AND pa.date = '2013-07-12'     ) AS percentage;
SELECT player_name FROM (     SELECT          player_name,         RANK() OVER (ORDER BY height DESC) AS height_rank     FROM Player ) ranked_players WHERE height_rank = 1;
SELECT player_api_id FROM Player ORDER BY weight DESC LIMIT 10;
SELECT     p.player_name FROM     Player AS p WHERE     datetime(CURRENT_TIMESTAMP, 'localtime') - datetime(p.birthday) > 34;
SELECT SUM(m.home_team_goal) AS total_home_goals FROM Match m JOIN Player p ON m.home_player_1 = p.player_api_id WHERE p.player_name = 'Aaron Lennon';
SELECT     SUM(m.away_team_goal) AS total_away_goals FROM Match m JOIN Player p1     ON m.away_player_1 = p1.player_api_id    OR m.away_player_2 = p1.player_api_id    OR m.away_player_3 = p1.player_api_id    OR m.away_player_4 = p1.player_api_id    OR m.away_player_5 = p1.player_api_id    OR m.away_player_6 = p1.player_api_id    OR m.away_player_7 = p1.player_api_id    OR m.away_player_8 = p1.player_api_id    OR m.away_player_9 = p1.player_api_id    OR m.away_player_10 = p1.player_api_id    OR m.away_player_11 = p1.player_api_id JOIN Player p2     ON m.away_player_1 = p2.player_api_id    OR m.away_player_2 = p2.player_api_id    OR m.away_player_3 = p2.player_api_id    OR m.away_player_4 = p2.player_api_id    OR m.away_player_5 = p2.player_api_id    OR m.away_player_6 = p2.player_api_id    OR m.away_player_7 = p2.player_api_id    OR m.away_player_8 = p2.player_api_id    OR m.away_player_9 = p2.player_api_id    OR m.away_player_10 = p2.player_api_id    OR m.away_player_11 = p2.player_api_id WHERE p1.player_name = 'Daan Smith'   AND p2.player_name = 'Filipe Ferreira';
SELECT     SUM(m.home_team_goal) AS total_home_team_goal FROM Match AS m WHERE EXISTS (     SELECT 1     FROM Player AS p     WHERE p.player_api_id IN (             m.home_player_1,             m.home_player_2,             m.home_player_3,             m.home_player_4,             m.home_player_5,             m.home_player_6,             m.home_player_7,             m.home_player_8,             m.home_player_9,             m.home_player_10,             m.home_player_11         )       AND (             julianday(CURRENT_TIMESTAMP) - julianday(p.birthday)         ) / 365.25 <= 30 );
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id ORDER BY pa.overall_rating DESC LIMIT 1;
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE pa.potential = (SELECT MAX(potential) FROM Player_Attributes);
SELECT DISTINCT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE pa.attacking_work_rate = 'high';
SELECT     p.player_name FROM Player AS p JOIN Player_Attributes AS pa     ON p.player_api_id = pa.player_api_id WHERE pa.finishing = 1 ORDER BY p.birthday ASC LIMIT 1;
SELECT DISTINCT p.player_name FROM Player p JOIN Match m   ON p.player_api_id IN (        m.home_player_1, m.home_player_2, m.home_player_3, m.home_player_4, m.home_player_5,        m.home_player_6, m.home_player_7, m.home_player_8, m.home_player_9, m.home_player_10, m.home_player_11,        m.away_player_1, m.away_player_2, m.away_player_3, m.away_player_4, m.away_player_5,        m.away_player_6, m.away_player_7, m.away_player_8, m.away_player_9, m.away_player_10, m.away_player_11      ) JOIN Country c ON m.country_id = c.id WHERE c.name = 'Belgium';
SELECT DISTINCT     p.player_name,     c.name AS country FROM Player_Attributes pa JOIN Player p     ON pa.player_api_id = p.player_api_id JOIN Match m     ON p.player_api_id IN (         m.home_player_1, m.home_player_2, m.home_player_3, m.home_player_4, m.home_player_5,         m.home_player_6, m.home_player_7, m.home_player_8, m.home_player_9, m.home_player_10, m.home_player_11,         m.away_player_1, m.away_player_2, m.away_player_3, m.away_player_4, m.away_player_5,         m.away_player_6, m.away_player_7, m.away_player_8, m.away_player_9, m.away_player_10, m.away_player_11     ) JOIN Country c     ON m.country_id = c.id WHERE pa.vision > 89;
SELECT      c.name AS country_name,     AVG(p.weight) AS average_weight FROM      Player p JOIN      Match m ON p.player_api_id IN (         m.home_player_1, m.home_player_2, m.home_player_3, m.home_player_4, m.home_player_5,         m.home_player_6, m.home_player_7, m.home_player_8, m.home_player_9, m.home_player_10, m.home_player_11,         m.away_player_1, m.away_player_2, m.away_player_3, m.away_player_4, m.away_player_5,         m.away_player_6, m.away_player_7, m.away_player_8, m.away_player_9, m.away_player_10, m.away_player_11     ) JOIN      Country c ON m.country_id = c.id GROUP BY      c.name ORDER BY      average_weight DESC LIMIT 1;
SELECT T1.team_long_name FROM Team AS T1 JOIN Team_Attributes AS T2   ON T1.team_api_id = T2.team_api_id WHERE T2.buildUpPlaySpeedClass = 'Slow';
SELECT DISTINCT T.team_short_name FROM Team_Attributes TA JOIN Team T   ON TA.team_api_id = T.team_api_id WHERE TA.chanceCreationPassingClass = 'Safe';
SELECT AVG(p.height) AS average_height FROM Player p JOIN Match m   ON p.player_api_id IN (        m.home_player_1, m.home_player_2, m.home_player_3, m.home_player_4, m.home_player_5,        m.home_player_6, m.home_player_7, m.home_player_8, m.home_player_9, m.home_player_10, m.home_player_11,        m.away_player_1, m.away_player_2, m.away_player_3, m.away_player_4, m.away_player_5,        m.away_player_6, m.away_player_7, m.away_player_8, m.away_player_9, m.away_player_10, m.away_player_11      ) JOIN Country c   ON m.country_id = c.id WHERE c.name = 'Italy';
SELECT player_name FROM Player WHERE height > 180 ORDER BY player_name ASC LIMIT 3;
SELECT COUNT(*) AS count FROM Player WHERE player_name LIKE 'Aaron%'   AND birthday > '1990';
SELECT      (SELECT jumping FROM Player_Attributes WHERE id = 6) -      (SELECT jumping FROM Player_Attributes WHERE id = 23) AS difference;
SELECT     p.id FROM Player AS p JOIN Player_Attributes AS pa     ON p.player_api_id = pa.player_api_id WHERE pa.preferred_foot = 'right' ORDER BY pa.potential ASC LIMIT 5;
SELECT COUNT(*) FROM Player_Attributes WHERE preferred_foot = 'left'   AND crossing = (       SELECT MAX(crossing)       FROM Player_Attributes       WHERE preferred_foot = 'left'   );
SELECT      CAST(SUM(CASE WHEN stamina > 80 AND strength > 80 THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) AS percentage FROM Player_Attributes;
SELECT c.name FROM League l JOIN Country c ON l.country_id = c.id WHERE l.name = 'Poland Ekstraklasa';
SELECT     m.home_team_goal,     m.away_team_goal FROM Match AS m JOIN League AS l     ON m.league_id = l.id WHERE     m.date LIKE '2008-09-24%'     AND l.name = 'Belgium Jupiler League';
SELECT     pa.sprint_speed,     pa.agility,     pa.acceleration FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Alexis Blin';
SELECT DISTINCT     ta.buildUpPlaySpeedClass FROM Team_Attributes ta JOIN Team t     ON ta.team_api_id = t.team_api_id WHERE t.team_long_name = 'KSV Cercle Brugge';
SELECT COUNT(*) AS game_count FROM Match JOIN League ON Match.league_id = League.id WHERE League.name = 'Italy Serie A'   AND Match.season = '2015/2016';
SELECT MAX(m.home_team_goal) AS highest_home_score FROM Match m JOIN League l ON m.league_id = l.id WHERE l.name = 'Netherlands Eredivisie';
SELECT     pa.finishing,     pa.curve FROM Player p JOIN Player_Attributes pa     ON p.player_api_id = pa.player_api_id WHERE p.weight = (     SELECT MAX(weight)     FROM Player );
SELECT     l.name FROM Match AS m JOIN League AS l     ON m.league_id = l.id WHERE m.season = '2015/2016' GROUP BY     l.name ORDER BY     COUNT(m.id) DESC LIMIT 4;
SELECT T.team_long_name FROM Team T JOIN Match M ON T.team_api_id = M.away_team_api_id ORDER BY M.away_team_goal DESC LIMIT 1;
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id ORDER BY pa.overall_rating DESC LIMIT 1;
SELECT      CAST(COUNT(CASE WHEN p.height < 180 AND pa.overall_rating > 70 THEN 1 END) AS REAL) * 100 / COUNT(p.id) AS percentage FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id;
WITH male_admissions AS (     SELECT         SUM(CASE WHEN Admission = '+' THEN 1 ELSE 0 END) AS in_patient_count,         SUM(CASE WHEN Admission = '-' THEN 1 ELSE 0 END) AS out_patient_count     FROM Patient     WHERE SEX = 'M' ) SELECT     CASE         WHEN in_patient_count > out_patient_count THEN 'in-patient'         WHEN out_patient_count > in_patient_count THEN 'outpatient'         ELSE 'equal'     END AS category,     ABS(in_patient_count - out_patient_count) * 100.0 / NULLIF(out_patient_count, 0) AS deviation_percentage FROM male_admissions;
SELECT      CAST(SUM(CASE WHEN strftime('%Y', Birthday) > '1930' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(ID) AS percentage FROM Patient WHERE SEX = 'F';
SELECT      CAST(SUM(CASE WHEN p.Admission = '+' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) AS percentage FROM      Patient p WHERE      p.Birthday BETWEEN '1930-01-01' AND '1940-12-31';
SELECT      CAST(SUM(CASE WHEN Diagnosis = 'SLE' AND Admission = '+' THEN 1 ELSE 0 END) AS REAL) * 1.0 /      NULLIF(SUM(CASE WHEN Diagnosis = 'SLE' AND Admission = '-' THEN 1 ELSE 0 END), 0) AS ratio FROM Patient;
SELECT      p.Diagnosis,     l.Date FROM      Patient p JOIN      Laboratory l ON p.ID = l.ID WHERE      p.ID = 30609;
SELECT      p.SEX,     p.Birthday,     e.`Examination Date`,     e.Symptoms FROM Patient p JOIN Examination e ON p.ID = e.ID WHERE p.ID = 163109;
SELECT     p.ID,     p.SEX,     p.Birthday FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE l.LDH > 500;
SELECT      p.ID,     (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) AS age FROM      Patient p JOIN      Examination e ON p.ID = e.ID WHERE      e.RVVT = '+';
SELECT     p.ID,     p.SEX,     p.Diagnosis FROM Patient AS p JOIN Examination AS e     ON p.ID = e.ID WHERE e.Thrombosis = 2;
SELECT DISTINCT p.ID FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE strftime('%Y', p.Birthday) = '1937'   AND l.`T-CHO` >= 250;
SELECT     p.ID,     p.SEX,     p.Diagnosis FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE l.ALB < 3.5;
SELECT      CAST(SUM(CASE WHEN p.SEX = 'F' AND (l.TP < 6.0 OR l.TP > 8.5) THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(p.ID) AS percentage FROM Patient p JOIN Laboratory l ON p.ID = l.ID;
SELECT AVG(e.`aCL IgG`) AS avg_acl_igg FROM Examination e JOIN Patient p ON e.ID = p.ID WHERE p.Admission = '+'   AND (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) >= 50;
SELECT COUNT(*) AS count FROM Patient WHERE SEX = 'F'   AND STRFTIME('%Y', `Description`) = '1997'   AND Admission = '-';
SELECT MIN(SUBSTR(`First Date`, 1, 4) - SUBSTR(`Birthday`, 1, 4)) AS age FROM `Patient` WHERE `First Date` IS NOT NULL   AND `Birthday` IS NOT NULL;
SELECT COUNT(*) AS count FROM Examination AS e JOIN Patient AS p   ON e.ID = p.ID WHERE e.Thrombosis = 1   AND strftime('%Y', e.`Examination Date`) = '1997'   AND p.SEX = 'F';
SELECT MAX(CAST(STRFTIME('%Y', p.Birthday) AS INTEGER)) - MIN(CAST(STRFTIME('%Y', p.Birthday) AS INTEGER)) AS age_gap FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.TG >= 200;
SELECT      e.Symptoms,     e.Diagnosis FROM Examination e JOIN Patient p ON e.ID = p.ID WHERE e.Symptoms IS NOT NULL ORDER BY p.Birthday DESC LIMIT 1;
SELECT     CAST(COUNT(DISTINCT l.ID) AS REAL) / 12 AS average_male_patients_per_month FROM Laboratory l JOIN Patient p     ON l.ID = p.ID WHERE l.Date BETWEEN '1998-01-01' AND '1998-12-31'   AND p.SEX = 'M';
SELECT      l.Date AS laboratory_date,     (strftime('%Y', p.`First Date`) - strftime('%Y', p.Birthday)) AS age_at_arrival FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Diagnosis = 'SJS' ORDER BY p.Birthday DESC LIMIT 1;
SELECT      CAST(SUM(CASE WHEN p.SEX = 'M' AND l.UA <= 8.0 THEN 1 ELSE 0 END) AS REAL) * 1.0 /      NULLIF(SUM(CASE WHEN p.SEX = 'F' AND l.UA <= 6.5 THEN 1 ELSE 0 END), 0) AS ratio FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE (p.SEX = 'M' AND l.UA <= 8.0) OR (p.SEX = 'F' AND l.UA <= 6.5);
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p LEFT JOIN Examination e   ON p.ID = e.ID WHERE e.ID IS NULL    OR (strftime('%Y', e.`Examination Date`) - strftime('%Y', p.`First Date`)) >= 1;
SELECT COUNT(*) AS count FROM Examination AS e JOIN Patient AS p   ON e.ID = p.ID WHERE strftime('%Y', p.Birthday) < '18'   AND strftime('%Y', e.`Examination Date`) BETWEEN '1990' AND '1993';
SELECT COUNT(*) AS count FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE p.SEX = 'M'   AND l.`T-BIL` >= 2.0;
SELECT     e.Diagnosis FROM Examination AS e WHERE e.`Examination Date` BETWEEN '1985-01-01' AND '1995-12-31' GROUP BY e.Diagnosis ORDER BY COUNT(e.Diagnosis) DESC LIMIT 1;
SELECT AVG(1999 - strftime('%Y', p.Birthday)) AS average_age FROM Patient p JOIN Laboratory l   ON p.ID = l.ID WHERE l.Date BETWEEN '1991-10-01' AND '1991-10-30';
SELECT      (strftime('%Y', e.`Examination Date`) - strftime('%Y', p.`Birthday`)) AS age,     p.`Diagnosis` AS doctor_diagnosis FROM      Examination e JOIN      Patient p ON e.`ID` = p.`ID` JOIN      Laboratory l ON e.`ID` = l.`ID` AND e.`Examination Date` = l.`Date` WHERE      l.`HGB` = (         SELECT MAX(l2.`HGB`)         FROM Laboratory l2         JOIN Examination e2 ON l2.`ID` = e2.`ID` AND l2.`Date` = e2.`Examination Date`     );
SELECT      `ANA` FROM      `Examination` WHERE      `ID` = 3605340     AND `Examination Date` = '1996-12-02';
SELECT      CASE          WHEN T1.`T-CHO` < 250 THEN 'Yes'          ELSE 'No'      END AS `Is Normal` FROM `Laboratory` AS T1 WHERE T1.`ID` = 2927464    AND T1.`Date` = '1995-09-04';
SELECT     p.SEX FROM Patient AS p WHERE p.Diagnosis = 'AORTITIS' ORDER BY p.ID ASC LIMIT 1;
SELECT     e.`aCL IgM` FROM     Examination AS e JOIN     Patient AS p     ON e.ID = p.ID WHERE     p.`Diagnosis` = 'SLE'     AND p.`Description` = '1994-02-19'     AND e.`Examination Date` = '1993-11-12';
SELECT      CASE          WHEN p.SEX = 'M' THEN 'man'         WHEN p.SEX = 'F' THEN 'women'         ELSE p.SEX     END AS gender FROM      Patient p JOIN      Laboratory l ON p.ID = l.ID WHERE      l.Date = '1992-06-12'     AND l.GPT = 9;
SELECT     SUBSTR('1991-10-21', 1, 4) - SUBSTR(p.Birthday, 1, 4) AS age_at_time FROM     Laboratory l JOIN     Patient p     ON l.ID = p.ID WHERE     l.Date = '1991-10-21'     AND l.UA = 8.4;
SELECT COUNT(l.ID) AS total_laboratory_tests FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.`First Date` = '1991-06-13'   AND p.Diagnosis = 'SJS'   AND strftime('%Y', l.Date) = '1995';
SELECT     p.Diagnosis FROM     Patient p JOIN     Examination e     ON p.ID = e.ID WHERE     e.`Examination Date` = '1997-01-27'     AND e.Diagnosis = 'SLE';
SELECT     e.Symptoms FROM Examination AS e JOIN Patient AS p     ON e.ID = p.ID WHERE     p.Birthday = '1959-03-01'     AND e.`Examination Date` = '1993-09-27';
SELECT      SUM(CASE WHEN p.Birthday = '1959-02-18' AND l.Date LIKE '1981-11-%' THEN l.`T-CHO` ELSE 0 END) -     SUM(CASE WHEN p.Birthday = '1959-02-18' AND l.Date LIKE '1981-12-%' THEN l.`T-CHO` ELSE 0 END) AS decrease_rate FROM Patient p JOIN Laboratory l ON p.ID = l.ID;
SELECT DISTINCT p.ID FROM Patient p JOIN Examination e ON p.ID = e.ID WHERE p.Diagnosis LIKE '%Behcet%'   AND e.`Examination Date` >= '1997-01-01'   AND e.`Examination Date` < '1998-01-01';
SELECT COUNT(DISTINCT l.ID) AS patient_count FROM Laboratory l WHERE l.Date BETWEEN '1987-07-06' AND '1996-01-31'   AND l.GPT > 30   AND l.ALB < 4;
SELECT COUNT(*) AS count, ID FROM Patient WHERE SEX = 'F'   AND strftime('%Y', Birthday) = '1964'   AND Admission = '+' GROUP BY ID;
SELECT COUNT(*) FROM Examination WHERE Thrombosis = 2   AND `ANA Pattern` = 'S'   AND `aCL IgM` > (SELECT AVG(`aCL IgM`) FROM Examination) * 1.2;
SELECT      CAST(SUM(CASE WHEN L.UA <= 6.5 THEN 1 ELSE 0 END) AS REAL) * 100 /      CAST(SUM(CASE WHEN L.`U-PRO` > 0 AND L.`U-PRO` < 30 THEN 1 ELSE 0 END) AS REAL) AS percentage FROM Laboratory L WHERE L.`U-PRO` > 0 AND L.`U-PRO` < 30;
SELECT      CAST(SUM(CASE WHEN p.Diagnosis = 'BEHCET' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS percentage FROM      Patient p WHERE      p.SEX = 'M'     AND strftime('%Y', p.`First Date`) = '1981';
SELECT DISTINCT p.ID FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Admission = '-'   AND l.Date LIKE '1991-10%'   AND l.`T-BIL` < 2.0;
SELECT COUNT(*) AS count FROM Patient AS p JOIN Examination AS e ON p.ID = e.ID WHERE e.`ANA Pattern` <> 'P'   AND p.SEX = 'F'   AND p.Birthday BETWEEN '1980-01-01' AND '1989-12-31';
SELECT     p.SEX FROM     Patient p JOIN     Examination e ON p.ID = e.ID JOIN     Laboratory l ON p.ID = l.ID WHERE     e.Diagnosis = 'PSS'     AND l.CRP > 2     AND l.CRE = 1     AND l.LDH = 123;
SELECT AVG(l.ALB) AS average_alb FROM Laboratory l JOIN Patient p   ON l.ID = p.ID WHERE p.SEX = 'F'   AND l.PLT > 400   AND p.Diagnosis = 'SLE';
SELECT T1.Symptoms FROM Examination AS T1 JOIN Patient AS T2   ON T1.ID = T2.ID WHERE T2.Diagnosis = 'SLE' GROUP BY T1.Symptoms ORDER BY COUNT(T1.Symptoms) DESC LIMIT 1;
SELECT      p.`Description` AS first_documented_date,     p.`Diagnosis` AS disease FROM      `Patient` p WHERE      p.`ID` = 48473;
SELECT COUNT(*) AS count FROM Patient WHERE SEX = 'F'   AND Diagnosis = 'APS';
SELECT COUNT(DISTINCT T1.ID) AS patient_count FROM Patient AS T1 JOIN Laboratory AS T2   ON T1.ID = T2.ID WHERE strftime('%Y', T2.Date) = '1997'   AND NOT (T2.TP > 6 AND T2.TP < 8.5);
SELECT      CAST(SUM(CASE WHEN e.Diagnosis LIKE '%SLE%' THEN 1 ELSE 0 END) AS REAL) * 100 /      SUM(CASE WHEN e.Symptoms LIKE '%thrombocytopenia%' THEN 1 ELSE 0 END) AS proportion FROM Examination e WHERE e.Symptoms LIKE '%thrombocytopenia%';
SELECT      CAST(SUM(CASE WHEN p.SEX = 'F' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(p.SEX) AS percentage FROM      Patient p WHERE      strftime('%Y', p.Birthday) = '1980'     AND p.Diagnosis = 'RA';
SELECT COUNT(*) AS count FROM Patient AS p JOIN Examination AS e ON p.ID = e.ID WHERE p.SEX = 'M'   AND e.`Examination Date` BETWEEN '1995-01-01' AND '1997-12-31'   AND e.Diagnosis = 'Behcet'   AND p.Admission = '-';
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.SEX = 'F'   AND l.WBC < 3.5;
SELECT DATEDIFF(`Examination`.`Examination Date`, `Patient`.`First Date`) AS days FROM `Examination` JOIN `Patient` ON `Examination`.`ID` = `Patient`.`ID` WHERE `Patient`.`ID` = 821298;
SELECT      CASE          WHEN (p.SEX = 'M' AND l.UA > 8.0) OR (p.SEX = 'F' AND l.UA > 6.5)          THEN 'Yes'          ELSE 'No'      END AS Is_UA_Within_Normal_Range FROM      Patient p JOIN      Laboratory l ON p.ID = l.ID WHERE      p.ID = 57266;
SELECT      L."Date" FROM      Laboratory AS L WHERE      L.ID = 48473     AND L.GOT >= 60;
SELECT DISTINCT     p.ID,     p.SEX,     p.Birthday FROM Patient p JOIN Laboratory l     ON p.ID = l.ID WHERE l.GOT < 60   AND strftime('%Y', l.Date) = '1994';
SELECT DISTINCT p.ID FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.SEX = 'M'   AND l.GPT >= 60;
SELECT     p.Diagnosis FROM     Patient p JOIN     Laboratory l     ON p.ID = l.ID WHERE     l.GPT > 60 ORDER BY     p.Birthday ASC;
SELECT AVG(LDH) AS average_ldh FROM Laboratory WHERE LDH < 500;
SELECT      p.ID,     (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) AS age FROM      Patient p JOIN      Laboratory l ON p.ID = l.ID WHERE      l.LDH BETWEEN 600 AND 800;
SELECT      p.ID,     p.Admission FROM      Patient p JOIN      Laboratory l ON p.ID = l.ID WHERE      l.ALP < 300;
SELECT      p.ID,     CASE          WHEN l.ALP < 300 THEN 'Yes'          ELSE 'No'      END AS ALP_within_normal_range FROM      Patient p LEFT JOIN      Laboratory l ON p.ID = l.ID WHERE      p.Birthday = '1982-04-01';
SELECT     p.ID,     p.SEX,     p.Birthday FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE l.TP < 6.0;
SELECT     T1.ID,     T1.TP - 8.5 AS deviation FROM     Laboratory AS T1 JOIN     Patient AS T2     ON T1.ID = T2.ID WHERE     T2.SEX = 'F'     AND T1.TP > 8.5;
SELECT     p.ID,     p.SEX,     p.Birthday,     p.Description,     p.`First Date`,     p.Admission,     p.Diagnosis FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE     p.SEX = 'M'     AND (l.ALB <= 3.5 OR l.ALB >= 5.5) ORDER BY     p.Birthday DESC;
SELECT      p.ID,     CASE          WHEN l.ALB BETWEEN 3.5 AND 5.5 THEN 'Within Normal Range'         ELSE 'Not Within Normal Range'     END AS Albumin_Status FROM      Patient p LEFT JOIN      Laboratory l ON p.ID = l.ID WHERE      strftime('%Y', p.Birthday) = '1982';
SELECT      CAST(SUM(CASE WHEN T1.UA > 6.5 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS percentage FROM      Laboratory AS T1 JOIN      Patient AS T2 ON      T1.ID = T2.ID WHERE      T2.SEX = 'F';
WITH LatestLab AS (     SELECT         l.ID,         l.Date,         l.UA,         p.SEX,         ROW_NUMBER() OVER (PARTITION BY l.ID ORDER BY l.Date DESC) AS rn     FROM Laboratory l     JOIN Patient p ON l.ID = p.ID ) SELECT AVG(ll.UA) AS avg_ua FROM LatestLab ll WHERE ll.rn = 1   AND (       (ll.SEX = 'M' AND ll.UA < 8.0)       OR       (ll.SEX = 'F' AND ll.UA < 6.5)   );
SELECT     p.ID,     p.SEX,     p.Birthday FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE l.UN = 29;
SELECT     p.ID,     p.SEX,     p.Birthday FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE p.Diagnosis = 'RA'   AND l.UN < 30;
SELECT COUNT(*) AS count FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE p.SEX = 'M'   AND l.CRE >= 1.5;
SELECT      CASE          WHEN SUM(CASE WHEN p.SEX = 'M' THEN 1 ELSE 0 END) > SUM(CASE WHEN p.SEX = 'F' THEN 1 ELSE 0 END)          THEN 'True'          ELSE 'False'      END AS result FROM      Patient p JOIN      Laboratory l ON p.ID = l.ID WHERE      l.CRE >= 1.5;
SELECT     p.ID,     p.SEX,     p.Birthday FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE l.`T-BIL` = (     SELECT MAX(`T-BIL`)     FROM Laboratory     WHERE `T-BIL` IS NOT NULL );
SELECT      p.SEX,     GROUP_CONCAT(DISTINCT p.ID) AS PatientIDs FROM      Patient p JOIN      Laboratory l ON p.ID = l.ID WHERE      l.`T-BIL` >= 2.0 GROUP BY      p.SEX;
SELECT     p.ID,     l.`T-CHO` FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID ORDER BY     p.Birthday ASC,     l.`T-CHO` DESC LIMIT 1;
SELECT      CAST(SUM(JULIANDAY('now') - JULIANDAY(p.Birthday)) AS REAL) / 365.25 / COUNT(p.ID) AS average_age FROM      Patient p JOIN      Laboratory l ON p.ID = l.ID WHERE      p.SEX = 'M'     AND l.`T-CHO` >= 250;
SELECT DISTINCT     p.ID,     p.Diagnosis FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE l.TG > 300;
SELECT COUNT(DISTINCT p.ID) AS count FROM Patient p JOIN Laboratory l   ON p.ID = l.ID WHERE l.TG >= 200   AND (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) > 50;
SELECT DISTINCT p.ID FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Admission = '-'   AND l.CPK < 250;
SELECT COUNT(DISTINCT p.ID) AS male_patients_with_high_cpk FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.SEX = 'M'   AND strftime('%Y', p.Birthday) BETWEEN '1936' AND '1956'   AND l.CPK >= 250;
SELECT      p.ID,     p.SEX,     (strftime('%Y', CURRENT_TIMESTAMP) - strftime('%Y', p.Birthday)) AS age FROM      Patient p JOIN      Laboratory l ON p.ID = l.ID WHERE      l.GLU >= 180     AND l.`T-CHO` < 250;
SELECT     p.ID,     l.GLU FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE     strftime('%Y', p.Description) = '1991'     AND l.GLU < 180;
SELECT      p.ID,     p.SEX,     p.Birthday FROM      Patient p JOIN      Laboratory l ON p.ID = l.ID WHERE      (l.WBC <= 3.5 OR l.WBC >= 9.0) ORDER BY      p.SEX,     p.Birthday DESC;
SELECT     p.ID,     p.Diagnosis,     (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) AS age FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE l.RBC < 3.5;
SELECT      p.ID,     p.SEX,     p.Birthday,     p.Admission,     l.RBC FROM      Patient p JOIN      Laboratory l ON p.ID = l.ID WHERE      p.SEX = 'F'     AND (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) >= 50     AND (l.RBC <= 3.5 OR l.RBC >= 6.0);
SELECT DISTINCT     p.ID,     p.SEX FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE p.Admission = '-'   AND l.HGB < 10;
SELECT     p.ID,     p.SEX FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE     p.Diagnosis = 'SLE'     AND l.HGB > 10     AND l.HGB < 17 ORDER BY     p.Birthday ASC LIMIT 1;
SELECT     p.ID,     (strftime('%Y', CURRENT_TIMESTAMP) - strftime('%Y', p.Birthday)) AS age FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE l.HCT >= 52 GROUP BY p.ID HAVING COUNT(l.ID) > 2;
SELECT AVG(HCT) FROM Laboratory WHERE Date LIKE '1991%'   AND HCT < 29;
SELECT      SUM(CASE WHEN PLT < 100 THEN 1 ELSE 0 END) - SUM(CASE WHEN PLT > 400 THEN 1 ELSE 0 END) AS difference FROM Laboratory WHERE PLT <= 100 OR PLT >= 400;
SELECT DISTINCT     p.ID FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE     strftime('%Y', l.Date) = '1984'     AND (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) < 50     AND l.PLT BETWEEN 100 AND 400;
SELECT      CAST(SUM(CASE WHEN L.PT >= 14 AND P.SEX = 'F' THEN 1 ELSE 0 END) AS REAL) * 100 /      SUM(CASE WHEN L.PT >= 14 THEN 1 ELSE 0 END) AS percentage FROM      Laboratory L JOIN      Patient P ON L.ID = P.ID WHERE      (strftime('%Y', 'now') - strftime('%Y', P.Birthday)) > 55;
SELECT DISTINCT p.ID FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE strftime('%Y', p.`First Date`) > '1992'   AND l.PT < 14;
SELECT COUNT(*) AS count FROM Examination AS e JOIN Laboratory AS l   ON e.ID = l.ID  AND e.`Examination Date` = l.Date WHERE e.`Examination Date` > '1997-01-01'   AND l.APTT < 45;
SELECT COUNT(DISTINCT e.ID) AS count FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE l.APTT > 45   AND e.Thrombosis = 0;
SELECT COUNT(DISTINCT p.ID) AS count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.SEX = 'M'   AND l.WBC > 3.5   AND l.WBC < 9.0   AND (l.FG <= 150 OR l.FG >= 450);
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Birthday > '1980-01-01'   AND (l.FG < 150 OR l.FG > 450);
SELECT DISTINCT p.Diagnosis FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.`U-PRO` >= 30;
SELECT DISTINCT p.ID FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Diagnosis = 'SLE'   AND l.`U-PRO` IS NOT NULL   AND l.`U-PRO` > 0   AND l.`U-PRO` < 30;
SELECT COUNT(DISTINCT T1.ID) FROM Patient AS T1 JOIN Laboratory AS T2   ON T1.ID = T2.ID WHERE T2.IGG >= 2000;
SELECT COUNT(*) AS count FROM Examination AS e JOIN Laboratory AS l   ON e.ID = l.ID WHERE l.IGG > 900   AND l.IGG < 2000   AND e.Symptoms IS NOT NULL;
SELECT p.Diagnosis FROM Laboratory l JOIN Patient p ON l.ID = p.ID WHERE l.IGA BETWEEN 80 AND 500 ORDER BY l.IGA DESC LIMIT 1;
SELECT COUNT(*) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.IGA > 80   AND l.IGA < 500   AND p.`First Date` IS NOT NULL   AND strftime('%Y', p.`First Date`) >= '1990';
SELECT     p.Diagnosis FROM     Patient p JOIN     Laboratory l     ON p.ID = l.ID WHERE     (l.IGM <= 40 OR l.IGM >= 400) GROUP BY     p.Diagnosis ORDER BY     COUNT(p.Diagnosis) DESC LIMIT 1;
SELECT COUNT(*) AS count FROM Patient WHERE Description IS NULL   AND EXISTS (       SELECT 1       FROM Laboratory       WHERE Laboratory.ID = Patient.ID         AND Laboratory.CRP = '+'   );
SELECT COUNT(*) AS count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.CRE >= 1.5   AND (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) < 70;
SELECT COUNT(DISTINCT e.ID) AS count FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE e.KCT = '+'   AND l.RA IN ('-', '+-');
SELECT DISTINCT p.Diagnosis FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Birthday >= '1985-01-01'   AND l.RA IN ('-', '+-');
SELECT DISTINCT p.ID FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.RF < 20   AND (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) > 60;
SELECT COUNT(*) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID JOIN Examination e ON p.ID = e.ID WHERE l.RF < 20   AND e.Thrombosis = 0;
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID JOIN Examination e ON p.ID = e.ID WHERE l.C3 > 35   AND e.`ANA Pattern` = 'P';
SELECT     e.ID FROM Examination AS e JOIN Laboratory AS l     ON e.ID = l.ID WHERE l.HCT IS NOT NULL   AND (l.HCT <= 29 OR l.HCT >= 52) ORDER BY e.`aCL IgA` DESC LIMIT 1;
SELECT COUNT(DISTINCT T1.ID) FROM Examination AS T1 JOIN Laboratory AS T2   ON T1.ID = T2.ID WHERE T1.Diagnosis = 'APS'   AND T2.C4 > 10;
SELECT COUNT(DISTINCT p.ID) FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE l.RNP IN ('-', '+-')   AND p.Admission = '+';
SELECT     p.Birthday FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE l.RNP NOT IN ('-', '+-') ORDER BY p.Birthday DESC LIMIT 1;
SELECT COUNT(*) AS count FROM Examination AS e JOIN Laboratory AS l   ON e.ID = l.ID WHERE l.SM IN ('-', '+-')   AND e.Thrombosis = 0;
SELECT p.ID FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE l.SM NOT IN ('negative', '0') ORDER BY p.Birthday DESC LIMIT 3;
SELECT DISTINCT e.ID FROM Examination e JOIN Laboratory l   ON e.ID = l.ID  AND e.`Examination Date` = l.Date WHERE e.`Examination Date` > '1997-01-01'   AND l.SC170 IN ('negative', '0');
SELECT COUNT(DISTINCT p.ID) AS count FROM Patient p JOIN Laboratory l   ON p.ID = l.ID JOIN Examination e   ON p.ID = e.ID WHERE l.SC170 IN ('negative', '0')   AND p.SEX = 'F'   AND e.Symptoms IS NULL;
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p JOIN Laboratory l   ON p.ID = l.ID WHERE l.SSA IN ('-', '+-')   AND p.`First Date` IS NOT NULL   AND strftime('%Y', p.`First Date`) < '2000';
SELECT p.ID FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE l.SSA NOT IN ('negative', '0') ORDER BY p.`First Date` ASC LIMIT 1;
SELECT COUNT(DISTINCT e.ID) AS patient_count FROM Examination e WHERE e.Diagnosis = 'SLE'   AND e.SSB IN ('-', '+-');
SELECT COUNT(DISTINCT e.ID) AS count FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE l.SSB IN ('negative', '0')   AND e.Symptoms IS NOT NULL;
SELECT COUNT(DISTINCT p.ID) AS male_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.CENTROMEA IN ('-', '+-')   AND l.SSB IN ('-', '+-')   AND p.SEX = 'M';
SELECT DISTINCT p.Diagnosis FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.DNA >= 8;
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.DNA < 8   AND p.Description IS NULL;
SELECT COUNT(*) AS count FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE l.IGG > 900   AND l.IGG < 2000   AND p.Admission = '+';
SELECT      CAST(SUM(CASE WHEN l.GOT >= 60 AND p.Diagnosis = 'SLE' THEN 1 ELSE 0 END) AS REAL) * 100.0 /      NULLIF(SUM(CASE WHEN l.GOT >= 60 THEN 1 ELSE 0 END), 0) AS percentage FROM Laboratory l JOIN Patient p ON l.ID = p.ID;
SELECT COUNT(*) FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE p.SEX = 'M'   AND l.GOT < 60;
SELECT MIN(p.Birthday) AS youngest_birthday FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.GOT >= 60;
SELECT      p.Birthday FROM      Patient p JOIN      Laboratory l ON p.ID = l.ID WHERE      l.GPT < 60 ORDER BY      l.GPT DESC LIMIT 3;
SELECT COUNT(*) AS male_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.GOT < 60   AND p.SEX = 'M';
SELECT MIN(p."First Date") FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.LDH < 500 ORDER BY l.LDH DESC LIMIT 1;
SELECT MAX(T2.Date) FROM Patient AS T1 JOIN Laboratory AS T2   ON T1.ID = T2.ID WHERE T1.ID = (     SELECT ID     FROM Patient     WHERE "First Date" IS NOT NULL     ORDER BY "First Date" DESC     LIMIT 1 )   AND T2.LDH >= 500;
SELECT COUNT(*) AS admitted_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.ALP >= 300   AND p.Admission = '+';
SELECT COUNT(*) AS count FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE p.Admission = '-'   AND l.ALP < 300;
SELECT DISTINCT p.Diagnosis FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.TP < 6.0;
SELECT COUNT(*) AS count FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE p.Diagnosis = 'SJS'   AND l.TP > 6.0   AND l.TP < 8.5;
SELECT     e.`Examination Date` FROM Examination AS e JOIN Laboratory AS l     ON e.ID = l.ID WHERE l.ALB > 3.5   AND l.ALB < 5.5 ORDER BY l.ALB DESC LIMIT 1;
SELECT COUNT(*) FROM Patient AS P JOIN Laboratory AS L ON P.ID = L.ID WHERE P.SEX = 'M'   AND L.ALB > 3.5   AND L.ALB < 5.5   AND L.TP BETWEEN 6.0 AND 8.5;
SELECT     e.`aCL IgG`,     e.`aCL IgM`,     e.`aCL IgA` FROM Examination AS e JOIN Patient AS p     ON e.ID = p.ID JOIN Laboratory AS l     ON e.ID = l.ID WHERE     p.SEX = 'F'     AND l.UA > 6.50 ORDER BY     l.UA DESC LIMIT 1;
SELECT MAX(e.ANA) AS max_ana FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE l.CRE < 1.5;
SELECT     e.ID FROM Examination AS e JOIN Laboratory AS l     ON e.ID = l.ID WHERE l.CRE < 1.5 ORDER BY e.`aCL IgA` DESC LIMIT 1;
SELECT COUNT(DISTINCT p.ID) AS count FROM Patient p JOIN Laboratory l   ON p.ID = l.ID JOIN Examination e   ON p.ID = e.ID WHERE l.`T-BIL` >= 2.0   AND e.`ANA Pattern` LIKE '%P%';
SELECT     e.ANA FROM Examination AS e JOIN Laboratory AS l     ON e.ID = l.ID WHERE l.`T-BIL` < 2.0 ORDER BY l.`T-BIL` DESC LIMIT 1;
SELECT COUNT(DISTINCT p.ID) AS count FROM Patient p JOIN Laboratory l ON p.ID = l.ID JOIN Examination e ON p.ID = e.ID WHERE l.`T-CHO` >= 250   AND e.`KCT` = '-';
SELECT COUNT(DISTINCT e.ID) AS count FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE l.`T-CHO` < 250   AND e.`ANA Pattern` = 'P';
SELECT COUNT(*) AS count FROM Examination AS e JOIN Laboratory AS l   ON e.ID = l.ID WHERE l.TG < 200   AND e.Symptoms IS NOT NULL;
SELECT     p.Diagnosis FROM     Patient p JOIN     Laboratory l     ON p.ID = l.ID WHERE     l.TG < 200 ORDER BY     l.TG DESC LIMIT 1;
SELECT DISTINCT e.ID FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE e.Thrombosis = 0   AND l.CPK < 250;
SELECT COUNT(DISTINCT e.ID) AS count FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE l.CPK < 250   AND (e.KCT = '+' OR e.RVVT = '+' OR e.LAC = '+');
SELECT     p.Birthday FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE l.GLU > 180 ORDER BY p.Birthday ASC LIMIT 1;
SELECT COUNT(*) FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID JOIN Examination AS e   ON p.ID = e.ID WHERE l.GLU < 180   AND e.Thrombosis = 0;
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Admission = '+'   AND l.WBC BETWEEN 3.5 AND 9.0;
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Diagnosis = 'SLE'   AND l.WBC BETWEEN 3.5 AND 9.0;
SELECT DISTINCT p.ID FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Admission = '-'   AND (l.RBC <= 3.5 OR l.RBC >= 6.0);
SELECT COUNT(DISTINCT p.ID) AS count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.PLT > 100   AND l.PLT < 400   AND p.Diagnosis IS NOT NULL;
SELECT     l.PLT FROM Laboratory AS l JOIN Patient AS p     ON l.ID = p.ID WHERE     p.Diagnosis = 'MCTD'     AND l.PLT > 100     AND l.PLT < 400;
SELECT AVG(l.PT) AS average_prothrombin_time FROM Laboratory l JOIN Patient p ON l.ID = p.ID WHERE p.SEX = 'M'   AND l.PT < 14;
SELECT COUNT(DISTINCT e.ID) AS patient_count FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE e.Thrombosis IN (1, 2)   AND l.PT < 14;
SELECT m.major_name FROM member AS mem JOIN major AS m ON mem.link_to_major = m.major_id WHERE mem.first_name = 'Angela'   AND mem.last_name = 'Sanders';
SELECT COUNT(*) AS student_count FROM member m JOIN major ma ON m.link_to_major = ma.major_id WHERE ma.college = 'College of Engineering';
SELECT     m.first_name,     m.last_name FROM member AS m JOIN major AS mj     ON m.link_to_major = mj.major_id WHERE mj.department = 'Art and Design';
SELECT COUNT(*) AS student_count FROM attendance a JOIN event e ON a.link_to_event = e.event_id JOIN member m ON a.link_to_member = m.member_id WHERE e.event_name = 'Women''s Soccer'   AND m.position = 'Student_Club';
SELECT DISTINCT m.phone FROM member AS m JOIN attendance AS a ON m.member_id = a.link_to_member JOIN event AS e ON a.link_to_event = e.event_id WHERE e.event_name = 'Women''s Soccer';
SELECT COUNT(*) AS count FROM member m JOIN attendance a ON m.member_id = a.link_to_member JOIN event e ON a.link_to_event = e.event_id WHERE e.event_name = 'Women''s Soccer'   AND m.t_shirt_size = 'Medium';
SELECT e.event_name FROM event e JOIN attendance a ON e.event_id = a.link_to_event JOIN member m ON a.link_to_member = m.member_id WHERE m.position = 'Student_Club' GROUP BY e.event_id ORDER BY COUNT(a.link_to_event) DESC LIMIT 1;
SELECT m.college FROM member AS mem JOIN major AS m ON mem.link_to_major = m.major_id WHERE mem.position = 'Vice President';
SELECT DISTINCT e.event_name FROM event e JOIN attendance a ON e.event_id = a.link_to_event JOIN member m ON a.link_to_member = m.member_id WHERE m.first_name = 'Maya'   AND m.last_name = 'Mclean';
SELECT COUNT(*) FROM event e JOIN attendance a ON e.event_id = a.link_to_event JOIN member m ON a.link_to_member = m.member_id WHERE e.type = 'Student_Club'   AND m.first_name = 'Sacha'   AND m.last_name = 'Harrison'   AND CAST(SUBSTR(e.event_date, 1, 4) AS INTEGER) = 2019;
SELECT COUNT(*) AS meeting_count FROM event e JOIN attendance a ON e.event_id = a.link_to_event WHERE e.type = 'Meeting' GROUP BY e.event_id HAVING COUNT(a.link_to_member) > 10;
SELECT e.event_name FROM event e JOIN attendance a ON e.event_id = a.link_to_event WHERE e.type <> 'Fundraiser' GROUP BY e.event_id, e.event_name HAVING COUNT(e.event_id) > 20;
SELECT     CAST(COUNT(a.link_to_event) AS REAL) / COUNT(DISTINCT e.event_name) AS average_attendance FROM attendance AS a JOIN event AS e     ON a.link_to_event = e.event_id WHERE e.type = 'Meeting'   AND CAST(SUBSTR(e.event_date, 1, 4) AS INTEGER) = 2020;
SELECT expense_description FROM expense ORDER BY cost DESC LIMIT 1;
SELECT COUNT(*) AS member_count FROM member m JOIN major ma ON m.link_to_major = ma.major_id WHERE ma.major_name = 'Environmental Engineering';
SELECT DISTINCT     m.first_name,     m.last_name FROM member AS m JOIN attendance AS a     ON m.member_id = a.link_to_member JOIN event AS e     ON a.link_to_event = e.event_id WHERE e.event_name = 'Laugh Out Loud';
SELECT m.last_name FROM member m JOIN major maj ON m.link_to_major = maj.major_id WHERE maj.major_name = 'Law and Constitutional Studies';
SELECT z.county FROM member m JOIN zip_code z ON m.zip = z.zip_code WHERE m.first_name = 'Sherri'   AND m.last_name = 'Ramsey';
SELECT DISTINCT m.college FROM member mem JOIN major m ON mem.link_to_major = m.major_id WHERE mem.first_name = 'Tyler'   AND mem.last_name = 'Hewitt';
SELECT i.amount FROM income i JOIN member m ON i.link_to_member = m.member_id WHERE m.position = 'Vice President';
SELECT SUM(b.spent) AS total_spent FROM budget b JOIN event e ON b.link_to_event = e.event_id WHERE b.category = 'Food'   AND e.event_name = 'September Meeting';
SELECT      z.city,     z.state FROM member m JOIN zip_code z ON m.zip = z.zip_code WHERE m.position = 'President';
SELECT      m.first_name,     m.last_name FROM member m JOIN zip_code z ON m.zip = z.zip_code WHERE z.state = 'Illinois';
SELECT     b.spent FROM budget AS b JOIN event AS e     ON b.link_to_event = e.event_id WHERE     e.event_name = 'September Meeting'     AND b.category = 'Advertisement';
SELECT DISTINCT m.department FROM major m JOIN member mem ON mem.link_to_major = m.major_id WHERE mem.first_name = 'Pierce'    OR mem.last_name = 'Guidi';
SELECT SUM(b.amount) AS total_budgeted_amount FROM budget b JOIN event e ON b.link_to_event = e.event_id WHERE e.event_name = 'October Speaker';
SELECT      e.expense_id,     e.expense_description,     e.expense_date,     e.cost,     e.approved FROM expense e JOIN budget b ON e.link_to_budget = b.budget_id JOIN event ev ON b.link_to_event = ev.event_id WHERE ev.event_name = 'October Meeting'   AND ev.event_date = '2019-10-08';
SELECT AVG(e.cost) AS total_average_cost FROM expense e JOIN member m ON e.link_to_member = m.member_id WHERE m.first_name = 'Elijah'   AND m.last_name = 'Allen'   AND (     CAST(SUBSTR(e.expense_date, 6, 2) AS INTEGER) = 9     OR CAST(SUBSTR(e.expense_date, 6, 2) AS INTEGER) = 10   );
SELECT      SUM(CASE WHEN SUBSTR(e.event_date, 1, 4) = '2019' THEN b.spent ELSE 0 END) -     SUM(CASE WHEN SUBSTR(e.event_date, 1, 4) = '2020' THEN b.spent ELSE 0 END) AS difference FROM event e JOIN budget b ON e.event_id = b.link_to_event WHERE e.type = 'Student_Club';
SELECT location FROM event WHERE event_name = 'Spring Budget Review';
SELECT e.cost FROM expense AS e JOIN event AS ev ON e.link_to_budget = (     SELECT b.budget_id     FROM budget AS b     WHERE b.link_to_event = ev.event_id ) WHERE e.expense_description = 'Posters'   AND ev.event_date = '2019-09-04';
SELECT     b.remaining FROM     budget AS b WHERE     b.category = 'Food'     AND b.amount = (         SELECT             MAX(b2.amount)         FROM             budget AS b2         WHERE             b2.category = 'Food'     );
SELECT notes FROM income WHERE source = 'Fundraising'   AND date_received = '2019-09-14';
SELECT COUNT(*) AS major_count FROM major WHERE college = 'College of Humanities and Social Sciences';
SELECT phone FROM member WHERE first_name = 'Carlo'   AND last_name = 'Jacobs';
SELECT z.county FROM member m JOIN zip_code z ON m.zip = z.zip_code WHERE m.first_name = 'Adela'   AND m.last_name = 'O''Gallagher';
SELECT COUNT(*) AS exceeded_budget_count FROM budget b JOIN event e ON b.link_to_event = e.event_id WHERE e.event_name = 'November Meeting'   AND b.remaining < 0;
SELECT SUM(b.amount) AS total_budget_amount FROM budget b JOIN event e ON b.link_to_event = e.event_id WHERE e.event_name = 'September Speaker';
SELECT     e.status FROM event AS e JOIN budget AS b     ON e.event_id = b.link_to_event JOIN expense AS ex     ON b.budget_id = ex.link_to_budget WHERE     ex.expense_description = 'Post Cards, Posters'     AND ex.expense_date = '2019-8-20';
SELECT m.major_name FROM member AS mem JOIN major AS m ON mem.link_to_major = m.major_id WHERE mem.first_name = 'Brent'   AND mem.last_name = 'Thomason';
SELECT COUNT(*) AS count FROM member m JOIN major ma ON m.link_to_major = ma.major_id WHERE ma.major_name = 'Business'   AND m.t_shirt_size = 'Medium';
SELECT z.type FROM member m JOIN zip_code z ON m.zip = z.zip_code WHERE m.first_name = 'Christof' AND m.last_name = 'Nielson';
SELECT m.major_name FROM member AS mem JOIN major AS m ON mem.link_to_major = m.major_id WHERE mem.position = 'Vice President';
SELECT z.state FROM member m JOIN zip_code z ON m.zip = z.zip_code WHERE m.first_name = 'Sacha' AND m.last_name = 'Harrison';
SELECT m.department FROM member AS mem JOIN major AS m ON mem.link_to_major = m.major_id WHERE mem.position = 'President';
SELECT     i.date_received FROM income AS i JOIN member AS m     ON i.link_to_member = m.member_id WHERE     m.first_name = 'Connor'     AND m.last_name = 'Hilton'     AND i.source = 'Dues';
SELECT      m.first_name,     m.last_name FROM income i JOIN member m ON i.link_to_member = m.member_id WHERE i.source = 'Dues' ORDER BY i.date_received ASC LIMIT 1;
SELECT      SUM(CASE WHEN e.event_name = 'Yearly Kickoff' THEN b.amount ELSE 0 END) * 1.0 /      SUM(CASE WHEN e.event_name = 'October Meeting' THEN b.amount ELSE 0 END) AS ratio FROM budget b JOIN event e ON b.link_to_event = e.event_id WHERE b.category = 'Advertisement';
SELECT      (SUM(CASE WHEN b.category = 'Parking' THEN b.amount ELSE 0 END) * 100.0) /      (SUM(b.amount)) AS percentage FROM budget b JOIN event e ON b.link_to_event = e.event_id WHERE e.event_name = 'November Speaker';
SELECT SUM(e.cost) AS total_cost FROM expense e WHERE e.expense_description = 'Pizza';
SELECT COUNT(DISTINCT city) AS city_count FROM zip_code WHERE county = 'Orange County'   AND state = 'Virginia';
SELECT DISTINCT department FROM major WHERE college = 'College of Humanities and Social Sciences';
SELECT      z.city,     z.county,     z.state FROM member m JOIN zip_code z ON m.zip = z.zip_code WHERE m.first_name = 'Amy'   AND m.last_name = 'Firth';
SELECT e.expense_description FROM expense e JOIN budget b ON e.link_to_budget = b.budget_id WHERE b.remaining = (     SELECT MIN(remaining)     FROM budget );
SELECT DISTINCT m.* FROM member m JOIN attendance a ON m.member_id = a.link_to_member JOIN event e ON a.link_to_event = e.event_id WHERE e.event_name = 'October Meeting';
SELECT     m.college FROM     major AS m JOIN     member AS mem ON m.major_id = mem.link_to_major GROUP BY     m.college ORDER BY     COUNT(m.college) DESC LIMIT 1;
SELECT m.major_name FROM member mem JOIN major m ON mem.link_to_major = m.major_id WHERE mem.phone = '809-555-3360';
SELECT e.event_name FROM event e JOIN budget b ON e.event_id = b.link_to_event ORDER BY b.amount DESC LIMIT 1;
SELECT     e.expense_description FROM expense AS e JOIN member AS m     ON e.link_to_member = m.member_id WHERE     m.position = 'Vice President';
SELECT COUNT(*) AS member_count FROM attendance a JOIN event e ON a.link_to_event = e.event_id WHERE e.event_name = 'Women''s Soccer';
SELECT i.date_received FROM income i JOIN member m ON i.link_to_member = m.member_id WHERE m.first_name = 'Casey'   AND m.last_name = 'Mason';
SELECT COUNT(*) AS member_count FROM member m JOIN zip_code z ON m.zip = z.zip_code WHERE z.state = 'Maryland';
SELECT COUNT(*) AS event_count FROM attendance a JOIN member m ON a.link_to_member = m.member_id WHERE m.phone = '954-555-6240';
SELECT     m.first_name,     m.last_name FROM member AS m JOIN major AS mj     ON m.link_to_major = mj.major_id WHERE mj.department = 'School of Applied Sciences, Technology and Education';
SELECT     e.event_name FROM event AS e JOIN budget AS b     ON e.event_id = b.link_to_event WHERE e.status = 'Closed' ORDER BY     CASE         WHEN b.amount = 0 THEN 0         ELSE b.spent * 1.0 / b.amount     END DESC LIMIT 1;
SELECT COUNT(*) AS student_count FROM member WHERE position = 'President';
SELECT MAX(spent) AS highest_amount_of_budget_spend FROM budget;
SELECT COUNT(*) AS meeting_count FROM event WHERE type = 'Meeting'   AND CAST(SUBSTR(event_date, 1, 4) AS INTEGER) = 2020;
SELECT SUM(spent) AS total_spent FROM budget WHERE category = 'Food';
SELECT     m.first_name,     m.last_name FROM member AS m JOIN attendance AS a     ON m.member_id = a.link_to_member GROUP BY     m.member_id,     m.first_name,     m.last_name HAVING     COUNT(a.link_to_event) > 7;
SELECT DISTINCT m.first_name, m.last_name FROM member m JOIN major maj ON m.link_to_major = maj.major_id JOIN attendance a ON m.member_id = a.link_to_member JOIN event e ON a.link_to_event = e.event_id WHERE maj.major_name = 'Interior Design'   AND e.event_name = 'Community Theater';
SELECT      m.first_name,     m.last_name FROM member m JOIN zip_code z ON m.zip = z.zip_code WHERE z.city = 'Georgetown'   AND z.state = 'South Carolina';
SELECT COUNT(*) AS income_count FROM income i JOIN member m ON i.link_to_member = m.member_id WHERE m.first_name = 'Grant'   AND m.last_name = 'Gilmour';
SELECT     m.first_name,     m.last_name FROM member AS m JOIN income AS i     ON m.member_id = i.link_to_member WHERE i.amount > 40;
SELECT SUM(e.cost) AS total_expense FROM expense e JOIN budget b ON e.link_to_budget = b.budget_id JOIN event ev ON b.link_to_event = ev.event_id WHERE ev.event_name = 'Yearly Kickoff';
SELECT      m.first_name,     m.last_name FROM member m JOIN budget b ON m.member_id = b.link_to_event JOIN event e ON b.link_to_event = e.event_id WHERE e.event_name = 'Yearly Kickoff';
SELECT     m.first_name,     m.last_name,     i.source FROM member AS m JOIN income AS i     ON m.member_id = i.link_to_member WHERE i.amount = (     SELECT MAX(amount)     FROM income );
SELECT e.event_name FROM event e JOIN budget b ON e.event_id = b.link_to_event JOIN expense ex ON b.budget_id = ex.link_to_budget ORDER BY ex.cost ASC LIMIT 1;
SELECT      (SUM(CASE WHEN e.event_name = 'Yearly Kickoff' THEN ex.cost ELSE 0 END) * 100.0) / SUM(ex.cost) AS percentage FROM expense ex JOIN budget b ON ex.link_to_budget = b.budget_id JOIN event e ON b.link_to_event = e.event_id;
SELECT      SUM(CASE WHEN m.major_name = 'Finance' THEN 1 ELSE 0 END) * 1.0 /      NULLIF(SUM(CASE WHEN m.major_name = 'Physics' THEN 1 ELSE 0 END), 0) AS ratio FROM member mem JOIN major m ON mem.link_to_major = m.major_id;
SELECT source FROM income WHERE date_received BETWEEN '2019-09-01' AND '2019-09-30' ORDER BY amount DESC LIMIT 1;
SELECT      m.first_name,     m.last_name,     m.email FROM member AS m WHERE m.position = 'Secretary';
SELECT COUNT(*) AS member_count FROM member m JOIN major ma ON m.link_to_major = ma.major_id WHERE ma.major_name = 'Physics Teaching';
SELECT COUNT(*) AS member_count FROM attendance a JOIN event e ON a.link_to_event = e.event_id WHERE e.event_name = 'Community Theater'   AND CAST(SUBSTR(e.event_date, 1, 4) AS INTEGER) = 2019;
SELECT      COUNT(DISTINCT a.link_to_event) AS number_of_events_attended,     m.major_name AS major FROM member m JOIN attendance a ON m.member_id = a.link_to_member JOIN major m ON m.link_to_major = m.major_id WHERE m.first_name = 'Luisa' AND m.last_name = 'Guidi';
SELECT      SUM(b.spent) / COUNT(b.spent) AS average_spent FROM      budget b WHERE      b.category = 'Food'     AND b.event_status = 'Closed';
SELECT e.event_name FROM event e JOIN budget b ON e.event_id = b.link_to_event WHERE b.category = 'Advertisement' ORDER BY b.spent DESC LIMIT 1;
SELECT      CASE          WHEN COUNT(*) > 0 THEN 'Yes'          ELSE 'No'      END AS attended FROM      member m JOIN      attendance a ON m.member_id = a.link_to_member JOIN      event e ON a.link_to_event = e.event_id WHERE      m.first_name = 'Maya'      AND m.last_name = 'Mclean'      AND e.event_name = 'Women''s Soccer';
SELECT      (SUM(CASE WHEN e.type = 'Community Service' THEN 1 ELSE 0 END) * 100.0) / COUNT(e.event_id) AS percentage_share FROM      event e WHERE      e.event_date BETWEEN '2019-01-01' AND '2019-12-31';
SELECT e.cost FROM expense e JOIN event ev ON e.link_to_budget = (     SELECT b.budget_id     FROM budget b     WHERE b.link_to_event = ev.event_id ) WHERE e.expense_description = 'Posters'   AND ev.event_name = 'September Speaker';
SELECT t_shirt_size FROM member GROUP BY t_shirt_size ORDER BY COUNT(t_shirt_size) DESC LIMIT 1;
SELECT e.event_name FROM event e JOIN budget b ON e.event_id = b.link_to_event WHERE e.status = 'Closed'   AND b.remaining < 0 ORDER BY b.remaining ASC LIMIT 1;
SELECT     e.expense_description,     SUM(e.cost) AS total_value FROM expense AS e JOIN budget AS b     ON e.link_to_budget = b.budget_id JOIN event AS ev     ON b.link_to_event = ev.event_id WHERE     ev.event_name = 'October Meeting'     AND e.approved = 'Yes' GROUP BY     e.expense_description;
SELECT      b.category,     SUM(b.amount) AS amount_budgeted FROM budget b JOIN event e ON b.link_to_event = e.event_id WHERE e.event_name = 'April Speaker' GROUP BY b.category ORDER BY amount_budgeted ASC;
