SELECT      CAST(SUM(CASE WHEN Currency = 'EUR' THEN 1 ELSE 0 END) AS REAL) /      NULLIF(SUM(CASE WHEN Currency = 'CZK' THEN 1 ELSE 0 END), 0) AS ratio FROM customers;
SELECT c.CustomerID FROM yearmonth ym JOIN customers c ON ym.CustomerID = c.CustomerID WHERE c.Segment = 'LAM'   AND ym.Date BETWEEN '201201' AND '201212' ORDER BY ym.Consumption ASC LIMIT 1;
SELECT AVG(ym.Consumption) / 12 AS Average_Monthly_Consumption FROM yearmonth ym JOIN customers c ON ym.CustomerID = c.CustomerID WHERE c.Segment = 'SME'   AND ym.Date BETWEEN '201301' AND '201312';
SELECT     c.CustomerID FROM customers AS c JOIN yearmonth AS ym     ON c.CustomerID = ym.CustomerID WHERE     c.Currency = 'CZK'     AND ym.Date BETWEEN '201101' AND '201112' ORDER BY     ym.Consumption DESC LIMIT 1;
SELECT COUNT(DISTINCT c.CustomerID) AS customer_count FROM customers c JOIN yearmonth ym ON c.CustomerID = ym.CustomerID WHERE c.Segment = 'KAM'   AND ym.Date BETWEEN '201201' AND '201212'   AND ym.Consumption < 30000;
SELECT      SUM(CASE WHEN c.Currency = 'CZK' THEN ym.Consumption ELSE 0 END) -     SUM(CASE WHEN c.Currency = 'EUR' THEN ym.Consumption ELSE 0 END) AS difference_in_consumption FROM yearmonth ym JOIN customers c ON ym.CustomerID = c.CustomerID WHERE ym.Date BETWEEN '201201' AND '201212';
SELECT      strftime('%Y', t.Date) AS Year FROM      transactions_1k t JOIN      customers c ON t.CustomerID = c.CustomerID WHERE      c.Currency = 'EUR' GROUP BY      strftime('%Y', t.Date) ORDER BY      SUM(t.Amount) DESC LIMIT 1;
SELECT     c.Segment,     SUM(ym.Consumption) AS TotalConsumption FROM     yearmonth ym JOIN     customers c     ON ym.CustomerID = c.CustomerID GROUP BY     c.Segment ORDER BY     TotalConsumption ASC LIMIT 1;
SELECT      SUBSTR(y.Date, 1, 4) AS Year FROM      yearmonth y JOIN      customers c ON y.CustomerID = c.CustomerID WHERE      c.Currency = 'CZK' GROUP BY      SUBSTR(y.Date, 1, 4) ORDER BY      SUM(y.Consumption) DESC LIMIT 1;
SELECT     ym.Date FROM     yearmonth AS ym JOIN     customers AS c     ON ym.CustomerID = c.CustomerID WHERE     c.Segment = 'SME'     AND ym.Date BETWEEN '201301' AND '201312' ORDER BY     ym.Consumption DESC LIMIT 1;
WITH czech_customers AS (     SELECT c.CustomerID, c.Segment     FROM customers c     WHERE c.Currency = 'CZK' ), customer_consumption_2013 AS (     SELECT          cc.CustomerID,         cc.Segment,         SUM(ym.Consumption) AS total_consumption     FROM czech_customers cc     JOIN yearmonth ym ON cc.CustomerID = ym.CustomerID     WHERE ym.Date BETWEEN '201301' AND '201312'     GROUP BY cc.CustomerID, cc.Segment ), lowest_consumption_per_segment AS (     SELECT          Segment,         MIN(total_consumption) AS min_consumption     FROM customer_consumption_2013     GROUP BY Segment ), customers_with_lowest_consumption AS (     SELECT          cc.CustomerID,         cc.Segment,         cc.total_consumption     FROM customer_consumption_2013 cc     JOIN lowest_consumption_per_segment lcs ON cc.Segment = lcs.Segment AND cc.total_consumption = lcs.min_consumption ), segment_annual_average AS (     SELECT          Segment,         SUM(total_consumption) / COUNT(*) AS annual_average     FROM customers_with_lowest_consumption     GROUP BY Segment ) SELECT      (SELECT annual_average FROM segment_annual_average WHERE Segment = 'SME') -      (SELECT annual_average FROM segment_annual_average WHERE Segment = 'LAM') AS sme_lam_diff,     (SELECT annual_average FROM segment_annual_average WHERE Segment = 'LAM') -      (SELECT annual_average FROM segment_annual_average WHERE Segment = 'KAM') AS lam_kam_diff,     (SELECT annual_average FROM segment_annual_average WHERE Segment = 'KAM') -      (SELECT annual_average FROM segment_annual_average WHERE Segment = 'SME') AS kam_sme_diff;
WITH consumption_by_segment_year AS (     SELECT          c.Segment,         CAST(SUBSTR(ym.Date, 1, 4) AS INTEGER) AS Year,         SUM(ym.Consumption) AS TotalConsumption     FROM yearmonth ym     JOIN customers c ON ym.CustomerID = c.CustomerID     WHERE c.Currency = 'EUR'       AND c.Segment IN ('SME', 'LAM', 'KAM')       AND CAST(SUBSTR(ym.Date, 1, 4) AS INTEGER) IN (2012, 2013)     GROUP BY c.Segment, CAST(SUBSTR(ym.Date, 1, 4) AS INTEGER) ), segment_consumption AS (     SELECT          Segment,         SUM(CASE WHEN Year = 2012 THEN TotalConsumption ELSE 0 END) AS Consumption2012,         SUM(CASE WHEN Year = 2013 THEN TotalConsumption ELSE 0 END) AS Consumption2013     FROM consumption_by_segment_year     GROUP BY Segment ), segment_percentage AS (     SELECT          Segment,         (Consumption2013 - Consumption2012) AS IncreaseOrDecrease,         ((Consumption2013 - Consumption2012) / Consumption2013) * 100 AS PercentageOfIncrease     FROM segment_consumption     WHERE Consumption2013 != 0 ) SELECT      Segment,     PercentageOfIncrease FROM segment_percentage ORDER BY      CASE          WHEN PercentageOfIncrease = (SELECT MAX(PercentageOfIncrease) FROM segment_percentage) THEN 1         WHEN PercentageOfIncrease = (SELECT MIN(PercentageOfIncrease) FROM segment_percentage) THEN 2         ELSE 3     END;
SELECT SUM(Consumption) AS TotalConsumption FROM yearmonth WHERE CustomerID = 6   AND Date BETWEEN '201308' AND '201311';
SELECT      (SELECT COUNT(*)       FROM gasstations       WHERE Country = 'CZE' AND Segment = 'Discount') -     (SELECT COUNT(*)       FROM gasstations       WHERE Country = 'SVK' AND Segment = 'Discount') AS difference;
SELECT      (SELECT Consumption       FROM yearmonth       WHERE CustomerID = 7 AND Date = '201304') -     (SELECT Consumption       FROM yearmonth       WHERE CustomerID = 5 AND Date = '201304') AS difference;
SELECT      (SELECT COUNT(*)       FROM customers       WHERE Segment = 'SME' AND Currency = 'CZK') -      (SELECT COUNT(*)       FROM customers       WHERE Segment = 'SME' AND Currency = 'EUR') AS Amount_of_more_SMEs;
SELECT c.CustomerID FROM customers c JOIN yearmonth ym ON c.CustomerID = ym.CustomerID WHERE c.Segment = 'LAM'   AND c.Currency = 'EUR'   AND ym.Date = '201310' ORDER BY ym.Consumption DESC LIMIT 1;
SELECT      c.CustomerID,     SUM(ym.Consumption) AS TotalConsumption FROM      customers c JOIN      yearmonth ym ON c.CustomerID = ym.CustomerID WHERE      c.Segment = 'KAM' GROUP BY      c.CustomerID ORDER BY      TotalConsumption DESC LIMIT 1;
SELECT     SUM(ym.Consumption) AS total_consumption FROM yearmonth AS ym JOIN customers AS c     ON ym.CustomerID = c.CustomerID WHERE     c.Segment = 'KAM'     AND ym.Date = '201305';
WITH lam_customers AS (     SELECT          c.CustomerID,         COALESCE(SUM(ym.Consumption), 0) AS total_consumption     FROM customers c     LEFT JOIN yearmonth ym ON c.CustomerID = ym.CustomerID     WHERE c.Segment = 'LAM'     GROUP BY c.CustomerID ) SELECT      (COUNT(CASE WHEN total_consumption > 46.73 THEN 1 END) * 100.0 / COUNT(*)) AS percentage FROM lam_customers;
SELECT      gs.Country,     COUNT(*) AS TotalValueForMoneyGasStations FROM      gasstations gs WHERE      gs.Segment = 'Value for money' GROUP BY      gs.Country ORDER BY      TotalValueForMoneyGasStations DESC;
