WITH target_customer AS (     SELECT CustomerID     FROM transactions_1k     WHERE Date = '2012-08-25'       AND Price = 634.8 ), consumption_by_year AS (     SELECT         ym.CustomerID,         SUM(CASE WHEN ym.Date LIKE '2012%' THEN ym.Consumption ELSE 0 END) AS consumption_2012,         SUM(CASE WHEN ym.Date LIKE '2013%' THEN ym.Consumption ELSE 0 END) AS consumption_2013     FROM yearmonth ym     JOIN target_customer tc ON ym.CustomerID = tc.CustomerID     GROUP BY ym.CustomerID ) SELECT     (consumption_2012 - consumption_2013) / consumption_2012 AS consumption_decrease_rate FROM consumption_by_year;
SELECT      gs.GasStationID FROM      gasstations gs JOIN      transactions_1k t ON gs.GasStationID = t.GasStationID GROUP BY      gs.GasStationID ORDER BY      SUM(t.Amount) DESC LIMIT 1;
SELECT      CAST(SUM(CASE WHEN gs.Segment = 'Premium' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) AS percentage FROM gasstations gs WHERE gs.Country = 'SVK';
SELECT      SUM(t.Amount) AS total_amount_spent,     SUM(CASE WHEN ym.Date = '201201' THEN ym.Consumption ELSE 0 END) AS spent_jan_2012 FROM transactions_1k t LEFT JOIN yearmonth ym      ON t.CustomerID = ym.CustomerID WHERE t.CustomerID = 38508;
SELECT p.Description FROM products p JOIN transactions_1k t ON p.ProductID = t.ProductID GROUP BY p.ProductID, p.Description ORDER BY SUM(t.Amount) DESC LIMIT 5;
WITH customer_totals AS (     SELECT         t.CustomerID,         SUM(t.Price) AS total_price,         SUM(t.Amount) AS total_amount     FROM transactions_1k t     GROUP BY t.CustomerID ), ranked_customers AS (     SELECT         ct.CustomerID,         ct.total_price,         ct.total_amount,         ct.total_price / ct.total_amount AS avg_price_per_item,         ROW_NUMBER() OVER (ORDER BY ct.total_price DESC) AS rn     FROM customer_totals ct ) SELECT     rc.CustomerID,     rc.avg_price_per_item,     c.Currency FROM ranked_customers rc JOIN customers c ON rc.CustomerID = c.CustomerID WHERE rc.rn = 1;
SELECT gs.Country FROM transactions_1k t JOIN gasstations gs ON t.GasStationID = gs.GasStationID WHERE t.ProductID = 2 ORDER BY t.Price DESC LIMIT 1;
SELECT     ym.CustomerID,     ym.Consumption FROM     yearmonth AS ym JOIN     transactions_1k AS t     ON ym.CustomerID = t.CustomerID WHERE     t.ProductID = 5     AND t.Price / t.Amount > 29.00     AND ym.Date = '201208';
